programs.sol:
"""Negative pulse on an undifferentiated document prefix.

The pulse lasts through exact repetitions of the first token, then stops.
Its approximate size uses typography: opening punctuation is strongest,
short capitalized fragments intermediate, and digits/Han text weaker.
The remaining tiny, context-dependent activations are approximated by zero.
"""
import unicodedata
import regex

READS = ()


def pulse(text):
    word = text.strip()
    if not word:
        return -9.0 if '\n' in text else -13.0
    first = word[0]
    category = unicodedata.category(first)
    if word.isdigit():
        size = 10.6
    elif regex.search(r'\p{Script=Han}', word):
        size = 10.0
    elif first.isupper():
        size = 15.2 if len(word) <= 3 else 13.0
    elif len(word) == 1 and category == 'Ps':
        size = 24.0
    elif word == '"':
        size = 25.0
    elif word == "'" or category in ('Pi', 'Pf'):
        size = 21.0
    elif word == '#':
        size = 23.0
    elif first in '([{\"#*':
        size = 17.5
    elif word in ',;:)]}，、':
        size = 9.2
    else:
        size = 12.0
    size -= 3.0 * min(text.count('\n'), 2)
    return -size


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = pulse(prefix.token_strings[-1])
        carry = (document, token, True, value)
    else:
        doc, first_token, repeating, value = carry
        repeating = repeating and token == first_token
        carry = (doc, first_token, repeating, value)
    return carry, carry[3] if carry[2] else 0.0

"""A negative response to modal auxiliaries (can, will, should, etc.).
Strength depends on capitalization and a preceding subject. 'To' also responds
in semi-modal and enabling constructions. Closed grammatical lists extend this
to modal verbs in several other languages, including split-word completions.
Negations and auxiliary contractions get smaller responses. Everything else is
near zero. Only recent text is carried, and it resets between documents.
"""
import re

READS = ()
MODALS = {
    'can': -1.32, 'could': -1.64, 'will': -1.20, 'would': -1.34,
    'may': -1.53, 'might': -1.56, 'shall': -1.59, 'should': -1.46,
    'must': -1.32, 'cannot': -.79,
}
PEOPLE = {'i', 'we', 'you', 'he', 'she', 'they'}
DETERMINERS = {'the', 'a', 'an', 'my', 'your', 'his', 'her', 'our', 'their'}
TO = {
    'have': -1.30, 'has': -1.48, 'had': -1.26, 'having': -.94,
    'need': -.80, 'needs': -1.10, 'needed': -.35, 'able': -.87,
    'unable': -.28, 'going': -.77, 'ought': -.89, 'supposed': -1.15,
    'expected': -.64, 'expect': -.52, 'managed': -.80, 'manage': -.52,
    'want': -.22, 'wants': -.19, 'wanted': -.10, 'try': -.22,
    'trying': -.18, 'possible': -.57, 'likely': -.35,
}
RELATED = {
    'need': -.50, 'needs': -.44, 'needed': -.33, 'able': -.38,
    'ought': -.64, 'want': -.22, 'wants': -.32, 'wanted': -.22,
    'likely': -.29, 'probably': -.28, 'possible': -.18,
}
# Modal verb families: ability, obligation, and futurity.
FAMILIES = (
    (-2.0, 'может могут могу можешь можете можем мог могла могли можно'),
    (-1.3, 'должен должна должно должны следует необходимо нужно надо'),
    (-1.1, 'будет будут буду будешь будете будем'),
    (-2.4, 'peut peux peuvent pouvez pouvons pouvoir pourrait pourraient '
           'pourra pourrez pourrais pourront puisse puissent pouvait pu pouvant'),
    (-2.1, 'doit dois doivent devez devons devrait devraient devra devrez'),
    (-1.7, 'kann kannst können könnt konnte konnten könnte könnten'),
    (-1.2, 'muss müssen soll sollen sollte sollten darf dürfen möchte'),
    (-.7, 'wird werden würde würden'),
    (-2.2, 'puede puedes pueden puedo podemos pueda puedan poder podría '
           'podrían podrás podrías podremos podrán podía pudiera pudieran podido '
           'pode podem posso podes poderia poderão possa possam'),
    (-2.4, 'debe debes deben debo debemos deve devem deveria debería deberían'),
    (-2.5, 'può puoi possiamo possono potrebbe potrebbero potrà potremo '
           'potremmo potete potuto possa possano'),
    (-1.8, 'devi devono dobbiamo dovrebbe dovrebbero dovremo dovremmo dovrete'),
    (-1.8, 'kan kunt kunnen kon konden'),
    (-1.3, 'moet moeten zou zouden skal ska må måste kunne kunna skulle'),
    (-1.8, 'może mogą można musi muszą'),
    (-1.5, 'يمكن يجب يستطيع sẽ akan จะ'),
)
FOREIGN = {word: value for value, words in FAMILIES for word in words.split()}
PREFIXES = {w[:n]: value for w, value in FOREIGN.items()
            for n in range(5, len(w))}
CHINESE = {
    -.9: '可以 就可以 也可以 都可以 我可以 您可以 能够 能夠 不能 只能 才能',
    -.92: '可能 可能会 可能會',
    -.8: '也會 就会 就會 都会 都會 不会 不會',
    -.6: '需要 必须 必須 应该 應該 应当 應當 要',
    -.27: '将 將', -.23: '会', -.75: '會', -.61: '能', -.64: '可',
}
HAN = {word: value for value, words in CHINESE.items() for word in words.split()}
WORD = re.compile(r'[^\W\d_]+$', re.UNICODE)
ENABLES = re.compile(
    r'\b(?:allow(?:s|ed|ing)?|enabl(?:e|es|ed|ing)|permit(?:s|ted|ting)?)'
    r"(?:\s+(?!to\b)[\w'-]+){0,5}\s*$", re.I)
# Romance future/conditional endings, when the stem is in earlier tokens.
FUTURE = re.compile(
    r'.{3,}(?:er|ir)(?:ai|as|a|ons|ez|ont|ais|ait|ions|iez|aient|'
    r'à|ò|emo|emmo|anno|ebbe|ebbero|á|án|ía|ían)$', re.I)


def response(s, previous, tail):
    w, prev = s.strip().lower(), previous.strip().lower()
    boundary = s[:1].isspace() or not tail or not tail[-1].isalpha()
    if w in MODALS:
        if not boundary:
            return -.51
        if w in {'can', 'could'} and prev in PEOPLE:
            return -1.90 if w == 'can' else -2.02
        if s.strip().istitle():
            factor = .4 if w in {'can', 'could', 'will', 'may'} else .85
            return MODALS[w] * factor
        if w in {'can', 'could'} and prev in DETERMINERS:
            return -.56 if w == 'can' else -1.51
        if w in {'can', 'could'} and prev in {'how', 'why', 'what', 'when', 'where'}:
            return -1.06 if w == 'can' else -1.40
        if w in {'will', 'would'} and prev in {'i', 'we', 'you'}:
            return -.90 if w == 'will' else -1.17
        if w in {'will', 'would'} and prev in {'it', 'this', 'that', 'which', 'there'}:
            return -1.30 if w == 'will' else -1.47
        if w == 'will' and prev in DETERMINERS:
            return .06
        return MODALS[w]
    if w in {"'ll", '’ll'}:
        return -.68 if prev == 'i' else -1.04
    if w in {"'d", '’d'}:
        return -.43
    if w in {"'t", '’t'}:
        if prev in {'won', 'couldn', 'wouldn', 'shouldn', 'mustn', 'mightn'}:
            return -1.12
        return -.75 if prev == 'can' else -.42
    if boundary and w == 'to':
        if ENABLES.search(tail):
            return -.95
        match = WORD.search(tail.rstrip())
        return TO.get(match.group().lower() if match else prev, -.01)
    if boundary and w == 'not':
        if prev in MODALS:
            return -.82
        if prev in {'have', 'has', 'had'}:
            return -.58
        return .1 if prev == 'or' else -.28
    if boundary and w in RELATED:
        return RELATED[w]
    if w in HAN:
        return HAN[w]
    if boundary and w in FOREIGN:
        return FOREIGN[w]
    if w == 'pas' and boundary and s.strip().islower():
        return -1.78 if re.search(r"\bne\b|\bn['’]", tail[-45:]) else -.36
    if s.isalpha():
        match = WORD.search(tail + s)
        full = match.group().lower() if match else ''
        if full in FOREIGN:
            return FOREIGN[full]
        if not boundary and full in PREFIXES:
            return PREFIXES[full]
        if not boundary and FUTURE.fullmatch(full):
            return -1.0
        if full.rstrip('t') in {'couldn', 'wouldn', 'shouldn', 'mustn', 'mightn'}:
            return -2.0
    return .002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    return (doc, (tail + s)[-80:], s), response(s, previous, tail)

programs.haiku:
"""Modal verbs, negations and infinitive 'to': a negative bump on words that a bare verb follows.

The component is most negative on modal verbs (can, could, might, may, shall, must, should,
would, will) and on the modal verbs of other languages (deben, peuvent, kann, может, 可以 ...).
Weaker negative values sit on negations ("not", "n't", "cannot", French "pas") and on
"need"/"want". Infinitive "to" is negative only after words that take a bare verb ("have to",
"need to", "going to", "able to"), and near zero for prepositional "to". A modal right after
"the" is a noun ("the can") and stays at zero.
"""
READS = ()

MODALS = {  # typical activation of each English modal, its strength
    "can": -1.4, "could": -1.8, "might": -1.6, "may": -1.35, "shall": -1.5,
    "will": -1.15, "would": -1.35, "should": -1.45, "must": -1.35,
}
OTHER_MODALS = {  # modal verbs in Spanish, Portuguese, French, German, Italian, Russian, Dutch
    "deben", "debe", "peuvent", "peut", "pouvez", "doivent", "doit", "pourrait", "pueden",
    "puede", "puedo", "pueda", "podía", "podem", "pode", "poder", "pude", "pued", "pud",
    "kann", "können", "könnte", "konnte", "soll", "sollte", "sollten", "wird", "ska", "kan",
    "può", "potrà", "sera", "будет", "может", "могут", "можно", "должна", "можете", "сможете",
}
CHINESE_MODALS = {"可以": -0.9, "可能会": -1.4, "可能": -0.8, "可": -0.7, "能": -0.5, "要": -0.6, "需要": -0.5}
NEGATIONS = {"not": -0.3, "'t": -0.55, "cannot": -0.7, "pas": -0.6, "nicht": -0.4, "'ll": -0.9}
NEED_WANT = {"need": -0.5, "needs": -0.5, "want": -0.2, "wants": -0.3}
TO_STRONG = {"have", "has", "had", "having"}
TO_MEDIUM = {"need", "needs", "needed", "going", "able", "supposed", "ought", "managed"}
TO_WEAK = {"possible", "expected", "want", "wants", "try", "likely", "ability", "unable", "found"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().replace("’", "'")
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in MODALS:
        return None, 0.0 if before == "the" else MODALS[word]
    if word in OTHER_MODALS:
        return None, -1.5
    if word in CHINESE_MODALS:
        return None, CHINESE_MODALS[word]
    if word in NEGATIONS:
        return None, NEGATIONS[word]
    if word in NEED_WANT:
        return None, NEED_WANT[word]
    if word == "to":
        if before in TO_STRONG:
            return None, -1.3
        if before in TO_MEDIUM:
            return None, -0.8
        if before in TO_WEAK:
            return None, -0.3
    return None, 0.0

programs.sol:
"""Approximate the larger shallow responses, not the small lexical residuals.

Use word classes for the document's first token. Later, give negative pulses
on 0/1 following 3 (as in 30/31), and on the word 'thirty'.
Number-internal punctuation is remembered using a short text tail.
"""
import re

READS = ()
PREPOSITIONS = set("""
of to in for on with at by from as into about than over under between
through during before after without within until against among
""".split())
ARTICLES = {"a", "an", "the"}
CONJUNCTIONS = set("""
and or but nor yet so although because while if unless whether
""".split())
PRONOUNS = set("""
i you he she it we they me him her us them my your his its our their
myself yourself himself herself itself ourselves themselves
""".split())
NUMBER_END = re.compile(r"([0-9]+)([.,]?)$")


def initial_value(s):
    word = s.strip().lower()
    if s == "<|im_start|>":
        return 0.23
    if s == "<|endoftext|>":
        return -2.09
    if not word:
        return 0.28 if "\n" in s else -0.08
    if word.isdecimal():
        return -0.28
    if word in PREPOSITIONS:
        return -0.36
    if word in ARTICLES:
        return -0.25
    if word in CONJUNCTIONS:
        return 0.11
    if word in PRONOUNS:
        return -0.08
    return -0.20 if word.isascii() else -0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    tail = "" if first else carry[1]
    value = initial_value(s) if first else 0.0
    if not first:
        match = NUMBER_END.search(tail)
        if s in ("0", "1") and match and match[1].endswith("3"):
            leading = len(match[1]) == 1
            clock = (leading and match.start() > 0
                     and tail[match.start() - 1] == ":")
            if s == "0":
                value = -0.33 if leading else -0.14
                if match[2]:
                    value = -0.13
                elif clock:
                    value = -0.39
            else:
                value = -0.15 if leading else -0.024
                if match[2]:
                    value = -0.065 if match[2] == "." else 0.0
                elif clock:
                    value = -0.11
        elif s.strip().lower() == "thirty":
            value = -0.18
    return (doc, (tail + s)[-32:]), value

"""A sparse delimiter-and-grammar approximation, not a general text predictor.

Negative responses mark bracketed URLs, citations, and runtime placeholders.
C/C++ header names and selected markup names have positive responses.
After Chinese possession/negation words, closed grammatical classes supply
a smaller lexical response.
Everything else is zero. Constants summarize training measurements.
"""
READS = ()

# Standard library headers: containers/algorithms versus streams and C wrappers.
HEADERS = frozenset('''
    algorithm array bitset bits chrono complex deque exception fstream
    functional iterator list map memory mutex new numeric queue random set
    sstream stack stdexcept string thread tuple type_traits unordered_map
    unordered_set utility vector
'''.split())
C_HEADERS = frozenset('''
    ctype errno float inttypes locale math signal stdarg stdbool stddef
    stdint stdio stdlib time unistd wchar wctype cctype cerrno cfloat
    cinttypes clocale cmath csignal cstdarg cstdbool cstddef cstdint
    cstdio cstdlib cstring ctime cwchar cwctype
'''.split())
STREAMS = frozenset('iostream istream ostream ios iosfwd streambuf'.split())
OBJECTS = frozenset('nil anonymous module function'.split())
PLACEHOLDERS = frozenset('file FILE root diff response VERSION ROLE class'.split())
PRONOUNS = frozenset('''
    我 你 您 他 她 它 我们 我們 你们 你們 他们 他們 大家 自己
'''.split())
# Quantifiers, demonstratives, and interrogatives.
QUANTIFIERS = frozenset('''
    这 這 此 那 哪 谁 誰 什么 什麼 些 那么 那麼 那么多 那麼多
    多少 几 幾 几个 幾個 一个人 一個人
'''.split())
# Auxiliaries and nearby grammatical function words.
AUXILIARIES = frozenset('''
    可 可以 能 能够 能夠 敢 不 在 自 该 該 会 會 应 應 要
    需 需要 有 无法 無法 足以 足够 足夠
'''.split())


def chinese_value(text):
    if text in PRONOUNS or text in AUXILIARIES:
        return 1.65
    if text in QUANTIFIERS:
        return -1.65
    return 0.0


def angle_value(previous, text, recent):
    if text in ('http', 'https', 'URL'):
        return -8.1
    if text in ('@', '#'):
        return -5.3
    if text in OBJECTS:
        return -2.5
    if text in PLACEHOLDERS:
        return -1.4
    if text.lower() == 'project':
        return -2.5
    if text == 'limits':
        return 10.0
    if text in ('assert', 'cassert', 'thread'):
        return 5.8
    if text == 'string':
        return 3.4 if '#include' in recent else 1.4
    if text in HEADERS:
        return 2.6
    if text in STREAMS:
        return 1.3
    if text in C_HEADERS:
        return 0.8
    if text == 'thead':
        return 5.1
    if text in ('group', 'groupId', 'reference'):
        return 2.5
    if text in ('img', 'span') and previous.endswith('<'):
        return 0.65
    if text in ('head', 'title', 'meta', 'svg', 'em', 'th'):
        return 0.9
    if text in ('template', 'option', 'dependency'):
        return -0.6
    if text == '-\n':
        return -7.0
    if text == ' |':
        return -2.0
    return 0.0


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    value = 0.3 if text in ('http', 'https') else 0.0
    if previous.endswith(('<', '</')):
        value = angle_value(previous, text, recent)
    elif previous.endswith('['):
        if text in ('http', 'https'):
            value = -4.0
        elif text == '@':
            value = -1.35
        elif text == '–':
            value = -5.7
        elif len(text) >= 8 and set(text) == {'='}:
            value = -0.8
    elif previous.endswith('{'):
        if text == '#':
            value = -1.5
        elif text == '¶':
            value = -2.6
        elif text == '@':
            value = -1.35
        elif text in ('http', 'https'):
            value = -2.3
    elif previous == '|' and text == '-\n':
        value = -1.6
    elif previous.endswith(('有', '未', '没', '沒', '无', '無')):
        value = chinese_value(text)
    return (doc, text, (recent + text)[-160:]), value

"""Spelling cues centered on CH-like endings followed by liquid letters (l/r).

Share these cues across scripts by transliteration. Suppress ordinary English
word endings, and weaken clusters buried in longer, familiar tokens. A small
echo reaches the next alphabetic token. Separate minor cues cover document
starts, repeated middle dots, and Chinese 大胆/大膽 ('bold').
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import math
import re

READS = ()

# Short spelling clusters wholly inside the current token.
STEMS = {
    'chlor': -2.65, 'chr': -1.87, 'chor': -2.92,
    'chir': -1.48, 'chil': -1.15, 'choir': -0.82,
    'hr': -0.35, 'chy': -1.05,
}
# Initial letters of a continuation after a CH-like ending.
ENDINGS = {
    'lor': -7.20, 'ri': -2.97, 'li': -0.16,
    'l': -5.01, 'r': -1.32,
    'ir': -3.23, 'il': -2.60, 'or': -2.49, 'ol': -2.62,
    'er': -1.12, 'el': -1.21, 'al': -0.71, 'ur': -1.30,
    'v': -1.32, 'y': -0.75,
}

@lru_cache(maxsize=32768)
def roman(text):
    return anyascii(text).lower()


@lru_cache(maxsize=32768)
def common_english(text):
    return zipf_frequency(text, 'en') >= 3.5


def spelling(previous, current):
    word = current.strip()
    s = roman(word)
    value = 0.0
    for stem, amplitude in STEMS.items():
        if s.startswith(stem):
            extension = len(s) - len(stem)
            familiar = 0.15 if extension and common_english(s) else 1.0
            value = amplitude * familiar * math.exp(-0.55 * extension)
            break
    if word.lower().startswith(('чер', 'чёр')):
        extension = len(s) - 4
        familiar = 0.15 if extension and common_english(s) else 1.0
        value -= 1.27 * familiar * math.exp(-0.55 * extension)
    if not current[:1].isalpha():
        return value

    p = previous.lower()
    pr = roman(p[-8:])
    # These clusters can span several tokens, e.g. chl + or.
    if pr.endswith(('chl', 'khl', 'kl', 'cl')) and s.startswith(('or', 'ol')):
        value -= 4.26
    if pr.endswith(('cho', 'kho', 'che', 'khe', 'chi', 'khi', 'chlo', 'khlo')):
        if s.startswith(('r', 'l')):
            value -= 0.89 * (0.35 if pr.endswith(('scho', 'sche', 'schi')) else 1.0)

    if p.endswith(('sch', 'fch', 'nch', 'tch', 'rch', 'ч', 'č')):
        scale = 0.1
    elif p.endswith('ch'):
        match = re.search(r'[^\W\d_]+$', p)
        left_word = match.group() if match else ''
        scale = 0.0 if left_word != 'ch' and common_english(left_word) else 1.0
    elif p.endswith('х'):
        scale = 1.5
    elif p.endswith('χ'):
        scale = 1.2
    elif p.endswith(('チ', 'チャ', 'チェ', 'チョ')):
        scale = 0.35
    else:
        return value

    if s == 'r':
        response = -5.93
    elif s.startswith(('ao', 'ia', 'ang')):
        response = 0.56
    else:
        response = next((a for ending, a in ENDINGS.items()
                         if s.startswith(ending)), 0.0)
    return value + scale * response


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail, old = (b'', 0.0) if first else carry[1:]
    token = prefix.token_bytes[-1]
    current = token.decode('utf-8', errors='replace')
    previous = tail.decode('utf-8', errors='replace')
    cue = spelling(previous, current)
    value = -0.0016 + cue
    if current[:1].isalpha():
        value += 0.16 * old
    if first:
        value += 0.261
        if current.startswith('<|'):
            value -= 0.051
        if current.strip() and ord(current.strip()[0]) > 127:
            value -= 0.077
    word = current.strip()
    if word and set(word) == {'·'} and (len(word) > 1 or previous.endswith('·')):
        value += 1.10
    if ('大胆' in current or '大膽' in current
            or (previous.endswith('大') and word in ('胆', '膽'))):
        value -= 4.82
    return (doc, (tail + token)[-48:], cue), float(value)

"""A formatting-and-boundary approximation, not a general semantic detector.

Double backslashes are normally positive, but raw math/table line breaks
and selected TeX layout pieces are negative. Backslash-bang is positive. Smaller
rules cover letter spacing, page boilerplate, document-start case offsets,
and carriage-return-only starts. Keep only 300 characters of context.
"""
import re

READS = ()
# Ignore commands whose backslash is itself escaped.
TEX_COMMAND = re.compile(
    r'(?<!\\)\\(?:frac|begin|end|left|right|hline|hfill|quad|'
    r'math(?:bb|cal|rm|bf|it|sf|scr)|[bB]ig(?:g|l|r|gl|gr)?|'
    r'alpha|beta|sum|equiv|nonumber|notag|text|theta|cdot|phi|psi|'
    r'nu|eta|infty|int|sin|cos|leq?|geq?|tilde|overline|ar|sqrt|lambda)'
    r'(?![A-Za-z0-9])')
TABLE_CELL = re.compile(r'(?<!&)&(?!&)')
MATH_NOTATION = re.compile(r'[_^]\{|&=|\d\s*[+*/]\s*\d')
