"""A sparse approximation of document-start and repeated-separator spikes.

Most activity is small and is approximated by zero. Document-initial cased
words receive a negative baseline, larger without leading whitespace and for
uppercase initials. Large positive exceptions
include a leading 'Title:' header, a leading '12', a space-period first token,
and uninterrupted runs of paired middle dots or carriage returns. These are
format-specific responses, not a general detector of titles or numbers.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, opening, repeated = 0, '', token
    else:
        _, position, opening, repeated = carry
        position += 1
        if repeated != token:
            repeated = ''

    value = 0.0
    if position == 0:
        word = token.lstrip()
        if word and word[0].isupper():
            value = -0.14 if token[0].isspace() else -0.28
        elif word and word[0].islower():
            value = -0.02 if token[0].isspace() else -0.12

    if position == 0 and token == ' .':
        value = 3.78
    elif position == 1 and opening == 'Title' and token == ':':
        value = 3.96
    elif token == '2' and opening == '1' and position == 1:
        value = 2.82
    elif token == '2' and opening == '12' and position == 2:
        value = 1.20
    elif repeated == '··':
        value = 2.22
    elif repeated == '\r':
        value = 2.80

    if position < 2:
        opening += token
    return (doc, position, opening, repeated), value

"""A surface-formatting approximation with a stronger document-start response.

Opening code declarations tend to be negative, while an opening percent sign
is positive. The rest of the rules cover visible delimiters and typography;
ordinary text is approximated by a small baseline, not a lexical lookup.
This captures only a small part of the observed activation variation.
"""

import regex

READS = ()

TYPE_WORDS = frozenset(
    'int char float double long short bool boolean string void'.split()
)
BINDINGS = frozenset('const var let using function'.split())
IMPORTS = frozenset('package import from namespace include module'.split())
HAN_TEXT = regex.compile(r'\p{Script=Han}+')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or document != carry
    token = prefix.token_strings[-1]
    text = token.strip()
    spaced = bool(token and token[0].isspace())

    if text and len(text) >= 2 and set(text) == {'·'}:
        value = -0.94
    elif token == '<|endoftext|>':
        value = -3.20 if first else -0.012
    elif first:
        if token == '<!':
            value = -4.07
        elif text == '%':
            value = 1.18 if spaced else 1.53
        elif text in TYPE_WORDS:
            value = -0.75 if spaced else -2.0
        elif text in BINDINGS:
            value = -0.6 if spaced else -1.7
        elif text in IMPORTS:
            value = -0.11 if spaced else -0.65
        elif token.startswith('#'):
            value = -0.41
        elif token.startswith('//'):
            value = -0.38
        elif not text:
            value = -0.09
        elif spaced and text.isascii() and text.isalpha() and text.islower():
            value = 0.12
        elif text.isascii() and text.isdigit():
            value = 0.115
        else:
            value = 0.0
    elif token == '</think>':
        value = -0.14
    elif token == '<|im_end|>':
        value = -0.024
    elif text in ('://', 'www', '.com'):
        value = 0.10
    elif text == '，':
        value = -0.046
    elif HAN_TEXT.fullmatch(text):
        value = -0.013
    elif text and set(text) <= set("'\"\\"):
        value = 0.011
    elif text and set(text) == {'`'}:
        value = 0.022
    elif text and set(text) <= set('-−–—'):
        value = -0.007
    elif text == '{':
        value = -0.019
    else:
        value = 0.0015
    return document, value

"""Approximate two negative-response patterns: technical dotted numbers and
English descriptions ("is a ...", "a tool for ...", "country of ...").

Dotted-number rules distinguish small major versions, multi-part numbers,
version/language labels and path-like prefixes from ordinary decimals.
Descriptive rules use recent wordlike tokens; repeated copulas weaken the
article response. Smaller rules cover biographical phrases, source paths,
and person-denoting relational adjectives, often nationalities. These are
coarse surface-pattern estimates, not a full grammatical analysis.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
COPULAS = {'is', 'was', 'are', 'were', 'be', 'being', 'been', "'s", '’s'}
ARTICLES = {'a', 'an'}
LINKS = {'of', 'for', 'to', 'in', 'with', 'by', 'on', 'from',
         'that', 'which', 'who', 'where'}
TOOLS = {'tool', 'program', 'function', 'platform', 'system', 'framework',
         'guide', 'application', 'library', 'software', 'utility', 'utilities'}
GROUPS = {'collection', 'set', 'series', 'range', 'group', 'list', 'number',
          'array', 'kind', 'type', 'variety', 'suite', 'genus', 'family'}
RELEASE_TAGS = {'alpha', 'beta', 'rc', 'preview', 'snapshot', 'release', 'dev'}
DOTTED = re.compile(r'(\d+(?:\.\d+)*)\.$')
VERSION_LABEL = re.compile(
    r'(?:version|python|java|ruby|perl|php|node|npm|gcc|clang|v|go|rust|'
    r'release|http|https|mime-version|xml|jquery|bootstrap)\s*$', re.I)


@lru_cache(maxsize=8192)
def person_adjective(word):
    categories = wordnet.categories(word)
    return 'noun.person' in categories and 'adj.pert' in categories


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', [], 0)
    _, text, words, copulas = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    alphabetic = bool(re.fullmatch('[a-z]+', word))
    previous = words[-1] if words else ''
    subject = words[-2] if len(words) > 1 else ''
    near_article = any(w in ARTICLES for w in words[-6:])
    near_copula = any(w in COPULAS for w in words[-10:])
    value = 0.0

    # Descriptive articles and the links extending their noun phrases.
    if previous in COPULAS:
        if word == 'the':
            value -= 0.09
        if word in ARTICLES:
            value += -0.41 + 0.31 * min(copulas, 10) / 10
            if subject in {'there', 'here'}:
                value += 0.21
            if subject in {'this', 'that'}:
                value -= 0.29
            if text.rstrip().endswith((') is', ') was')):
                value -= 0.51
    if word in LINKS and near_article and near_copula:
        value -= 0.09
    if word in {'for', 'to', 'that'} and previous in TOOLS and near_article:
        value -= 0.61
    if word == 'of' and previous in GROUPS and near_article:
        value -= 0.12
    if previous in ARTICLES and alphabetic and person_adjective(word):
        value -= 0.28
    if word == 'of' and previous == 'country':
        value -= 0.49
    if word == 'born' and text.rstrip().endswith('('):
        value -= 0.37
    if token == '.mod' and text.endswith('go'):
        value -= 0.56
    if token in {'/src', '/lib', '/include'}:
        value -= 0.16

    # A dot and the first digit after it respond differently.
    digit = token.isascii() and token.isdigit()
    match = DOTTED.search(text) if digit else None
    fraction = match is not None
    if token == '.':
        match = DOTTED.search(text + '.')
    if match:
        number = match.group(1)
        before = text[:match.start()]
        part = number.split('.')[-1]
        multiple = '.' in number
        tight = bool(before) and before[-1] in '_/-^~vV@'
        labeled = bool(VERSION_LABEL.search(before))
        if fraction:
            value -= 0.15 * (len(part) == 1)
            value += 0.17 * (part == '0') - 0.37 * (part == '1')
            value -= 0.66 * multiple + 0.78 * tight + 1.41 * labeled
            if re.search(r'PASS|finished in|test result', before[-90:]):
                value -= 0.41
        else:
            value -= 0.39 * multiple + 0.23 * tight + 0.56 * labeled
    if word.lstrip('-._') in RELEASE_TAGS:
        if re.search(r'\d[.\-a-zA-Z]*$', text):
            value -= 0.94

    # Keep bounded history, and discard word history at sentence punctuation.
    if word in COPULAS:
        copulas += 1
    if alphabetic or word in COPULAS:
        words = (words + [word])[-16:]
    elif token.strip() and not token.strip().isalpha():
        if any(c in token for c in '.!?;\n'):
            words = []
    return (doc, (text + token)[-220:], words, copulas), value

programs.haiku:
"""Layer-1 MLP component 459 (down_proj, unit 459).

Negative in two places, near zero everywhere else:
  1. Software version numbers: on the digit after a dot ("Version 2.[0]", "v4.1.[0]",
     "pkg__1.[0]", "@1.[0]") and on that dot. Strongest after "v", "Version", "@", "__", "-";
     weaker after a bare space (prose decimals like "0.42" stay near zero); strongest for the
     second dot and for the digits 0 and 1.
  2. Definitions: "X is a/an ...". The article after "is"/"was" goes negative (strongest after
     "This" or a closing parenthesis, as in "X (1943) is a"), and so does the word that follows
     the head noun of the definition ("is a family [of]", "a mechanism [that]", "a module [for]").
"""

READS = ()

DIGITS = set("0123456789")
STRONG = {"v", "V", "version", "Version", "ver", "@", "^", '"^', "release", "__", "-"}
MEDIUM = {"/", '"'}
COPULAS = {" is", " was", " are", " were"}
ARTICLES = {" a", " an"}
BREAKS = {".", ",", "\n", "\n\n", "!", "?", ";", ":", "<|endoftext|>"}
DEF_WORDS = {" that": -0.6, " by": -0.7, " who": -0.45, " for": -0.4, " of": -0.15, " which": -0.3}


def version_marker(s, end):
    """Number of dots and the token before the dotted number that ends at index `end`."""
    j = end
    dots = 0
    while j >= 0 and (s[j] in DIGITS or s[j] == "."):
        dots += s[j] == "."
        j -= 1
    marker = s[j] if j >= 0 else ""
    if marker == " " and j >= 1:
        marker = s[j - 1].strip()
    if marker.endswith("ersion") or marker.endswith("v"):
        marker = "version"
    return dots, marker


def in_definition(s):
    """True if an 'is a/an' or 'was a/an' opens the current phrase (no break before now)."""
    for k in range(2, 7):
        if len(s) < k + 1:
            return False
        if s[-k] in ARTICLES and s[-k - 1] in COPULAS:
            return not any(x in BREAKS for x in s[-k + 1 : -1])
    return False


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    value = 0.0
    if cur in DIGITS and len(s) >= 3 and s[-2] == "." and s[-3] in DIGITS:
        dots, marker = version_marker(s, len(s) - 2)
        if marker in STRONG:
            value = -1.6
        elif marker in MEDIUM:
            value = -1.0
        if value and dots >= 2:
            value = -1.4
        if value and cur not in "01":
            value *= 0.6
    elif cur == "." and len(s) >= 2 and s[-2] in DIGITS:
        dots, marker = version_marker(s, len(s) - 2)
        if marker in {"__", "-"}:
            value = -0.35
        elif marker in STRONG:
            value = -0.85
        elif marker in MEDIUM:
            value = -0.5
        elif dots >= 1:
            value = -0.6
    elif cur in ARTICLES and len(s) >= 3 and s[-2] in COPULAS:
        subject = s[-3].strip()
        if subject in ("there", "There", "it", "It", "here", "Here"):
            value = 0.0
        elif subject in ("This", "this", ")"):
            value = -1.0
        else:
            value = -0.5
    elif cur in DEF_WORDS and in_definition(s):
        value = DEF_WORDS[cur]
    return carry, float(value)

programs.sol:
"""Approximate the component's local English determiner signal.

Lower-case determiners, especially 'the', are positive after interrogative
words and in partitives like 'one of the'. They are negative after copulas
and focus modifiers. Short context distinguishes 'what is the', 'this is
the', 'here are some', and 'not just the'. Possessives have weaker negative
responses. Small additional rules cover quoted 'the', 'a certain',
'a number', and 'just/simply because'. Everything else is near zero.

Only three preceding tokens are retained, resetting at document boundaries.
This approximation leaves the component's rare markup/navigation responses
unmodeled; it is not a general syntax parser.
"""
import re

READS = ()
POSSESSIVES = {'my', 'our', 'his', 'her', 'its', 'their'}
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being', 'am',
           'become', 'becomes', 'became', 'becoming', "'s", '’s',
           "'m", '’m', "'re", '’re'}
WH = {'what', 'whatever', 'who', 'whoever'}
MODALS = {'will', 'would', 'should', 'shall', 'can', 'could', 'may',
          'might', 'must', 'has', 'have', 'had'}


def word(token):
    if token.strip() in {"'s", '’s', "'t", '’t', "'m", '’m', "'re", '’re'}:
        return token.strip()
    m = re.search(r'[A-Za-z]+$', token)
    return m.group().lower() if m else ''


def predict(token, history):
    if token == 'the' and history and history[-1].strip() in {'"', '“'}:
        return -.5
    if token in {' certain', ' number'} and history:
        if word(history[-1]) == 'a':
            return -.9 if token == ' certain' else -.35
    if token == ' because' and history:
        if word(history[-1]) in {'just', 'simply'}:
            return -2.0
    if not token.startswith(' '):
        return 0.0
    current = token[1:]
    if current == 'the':
        negative_gain, positive_gain = 1.0, 1.0
    elif current == 'your':
        negative_gain, positive_gain = .65, .9
    elif current in POSSESSIVES:
        negative_gain, positive_gain = .2, .9
    elif current == 'some':
        negative_gain, positive_gain = .6, .65
    else:
        return 0.0
    prev = word(history[-1]) if history else ''
    prior = word(history[-2]) if len(history) > 1 else ''
    capital = (len(history) > 1 and
               any(c.isupper() for c in history[-2]))
    if prev in WH:
        value = 8.8 if prev in {'whatever', 'whoever'} else 6.5
        return value * positive_gain
    if prev in MODALS and prior in WH:
        return 3.7 * positive_gain
    if prev == 'matter' and prior == 'no':
        return 3.0 * positive_gain
    if prev in COPULAS:
        if prior in {'here', 'below'}:
            return 2.2 if current == 'some' else -.3
        if prior in MODALS and len(history) > 2 and word(history[-3]) in WH:
            return 2.5 * positive_gain
        if prior in {'who', 'whoever'}:
            return 1.0 * positive_gain
        if prior == 'which' and capital:
            return .3 * positive_gain
        if prior in WH:
            value = 6.3 if prev == 'are' else 4.0
            return (value + .7 * capital) * positive_gain
        value = -1.15
        if prev in {'are', 'were'}:
            value = -1.45
        elif prev in {'be', 'being', 'become', 'becoming'}:
            value = -1.65
        if prior == 'i' and prev in {'am', "'m", '’m'}:
            value -= .8
        if prior in {'this', 'these'}:
            value -= 1.2 + .4 * capital
        elif prior in {'that', 'those', 'it', 'which', 'there'}:
            value -= 1.1 if prev in {"'s", '’s'} else .55
        return value * negative_gain
    if prev == 'of':
        if prior == 'one':
            return (2.2 if capital else 1.2) * positive_gain
        if prior in {'some', 'any', 'few', 'several', 'many', 'both', 'two', 'three'}:
            return .45 * positive_gain
    if prev == 'this' and len(history) > 1 and prior in COPULAS:
        return -2.85 * negative_gain
    if prev in {'just', 'only', 'even', 'especially', 'particularly',
                'exactly', 'precisely', 'literally'}:
        value = -2.6
        if prev == 'just':
            value = -4.4
        elif prev == 'only':
            value = -3.0
        elif prev in {'especially', 'particularly'}:
            value = -3.5
        if prev in {'just', 'only'} and prior in {'not', "'t", '’t'}:
            value *= .3
        if history[-1].lstrip()[:1].isupper():
            value -= .6
        return value * negative_gain
    if prev in {'either', 'solely', 'simply', 'basically', 'essentially',
                'indeed', 'virtually', 'mostly', 'largely', 'primarily'}:
        return -1.8 * negative_gain
    if prev in {'also', 'always', 'often', 'likely', 'nearly', 'almost'}:
        return -1.3 * negative_gain
    if prev in {'not', "'t", '’t', 'actually', 'really'}:
        return -1.3 * negative_gain
    if prev in {'as', 'like', 'or'}:
        return -.85 * negative_gain
    if prev in {'perhaps', 'maybe', 'wait'}:
        return -.6 * negative_gain
    if prev in {'when', 'where', 'which'}:
        return .25 * positive_gain
    if prev == 'then':
        return -.2 * negative_gain
    if prev == 'but':
        return -.35 * negative_gain
    if prev == 'that':
        return -.19 * negative_gain
    if current == 'the':
        return -.025
    return .01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(token, history)
    return (doc, (history + (token,))[-3:]), value

