"""layers.1.mlp.down_proj:463 -- a "what-question determiner" detector.

Plain-language summary. The component writes to the residual stream mainly on the
word "the" (and a few other determiners: your, their, its, my, our, his, her, some).
Its activation depends on the word just before the determiner:

* Right after "what" / "whatever" (e.g. "what the results", "Whatever the cause"):
  strongly positive, about +7.
* Two words after "what", with a copula in between (e.g. "What is the", "What are the",
  "What's your"): positive, about +4.5.
* "one of the" (partitive): mildly positive, about +1.4.
* "the" right after a focus adverb (only, just, even, exactly, not, also ...): strongly
  negative, about -2.5.
* "the" right after a copula or "be" (is, are, was, were, be, been, 's ...): negative,
  about -1.0.
* "the" right after a conjunction or comparative word (as, like, or, than, but, that,
  perhaps, maybe ...): mildly negative, about -0.5.
* Everything else: 0.

The program reads only the current token and the two before it, so it has no carry.
"""

# Determiners the component responds to, and the words that set its sign.
WH_WORDS = {"what", "whatever"}
DETERMINERS = {"the", "your", "their", "its", "my", "our", "his", "her", "some"}
COPULAS = {"is", "are", "was", "were", "be", "being", "been", "'s", "’s"}
FOCUS_ADVERBS = {"only", "just", "even", "exactly", "especially", "also", "simply", "precisely", "either", "not"}
CONJUNCTIONS = {"as", "like", "or", "maybe", "perhaps", "than", "but", "that", "become", "became"}

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    prev2 = prefix.token_strings[-3].strip().lower() if len(prefix) > 2 else ""
    if word in DETERMINERS:
        if prev in WH_WORDS:
            return carry, 7.0
        if prev2 in WH_WORDS and prev in COPULAS:
            return carry, 4.5
        if prev2 == "one" and prev == "of":
            return carry, 1.4
    if word == "the":
        if prev in FOCUS_ADVERBS:
            return carry, -2.5
        if prev in COPULAS:
            return carry, -1.0
        if prev in CONJUNCTIONS:
            return carry, -0.5
    return carry, 0.0

programs.sol:
"""Approximate a key/value binding feature, rather than a general colon detector.

Object field colons are strongest, with separate estimates for quoted, escaped,
and spaced key spellings, and for first versus subsequent fields. Assignments,
mapping/function arrows, spread syntax and URL separators have smaller responses.
The syntax heuristics reject common prose, citation, subscript and declaration
contexts. Listings, diffs and escaped code are normalized before inspection.
Unmatched tokens give zero; a document boundary clears the trailing text buffer.
"""
import re

READS = ()


def clean(text):
    text = text.replace('\\n', '\n').replace('\\t', '\t')
    text = re.sub(r'\\+(["\'])', r'\1', text)
    text = re.sub(r'(?m)^[ \t]*\d+\t', '  ', text)
    return re.sub(r'(?m)^([ \t]*)(?:[+-]|//)', r'\1', text)


def open_bracket(text):
    text = re.sub(r'"[^"\n]*"|\'[^\'\n]*\'', 'x', text)
    stack = []
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}' and stack:
            stack.pop()
    return stack[-1] if stack else ''


def response(token, text):
    if token == '://':
        return 1.4
    if token == ' =':
        line = clean(text).split('\n')[-1]
        key = re.search(r'[A-Za-z_$][\w$]*$', line)
        if not key:
            return 0.27 if line.endswith(']') else -0.04
        if re.search(r'\b(const|let|var|int|auto|final)\s+', line):
            return 0.83
        return 0.5 if len(key.group()) > 1 else 0.17
    if token.strip() == ':=':
        return 0.84
    if token.strip() == '=>' or token == "'=>":
        tail = text.rstrip()
        character = re.search(r"(?:b)?'[^']'$", tail)
        if token == "'=>":
            character = re.search(r"(?:b)?'[^']$", tail)
        quoted = token == "'=>" or tail.endswith(('"', "'"))
        return 5.6 if quoted and not character else 0.82
    if token.strip() in ('...', '...('):
        return 3.8 if clean(text).rstrip().endswith((',', '[', '{')) else 0.0
    if ':' not in token:
        return 0.0
    before = clean(text)
    if token in ('":"', "':'"):
        return 1.2
    if token in (':"', ":'"):
        token = ':'
    if token.endswith(('":', "':")):
        quote = token[-2]
    elif token in (':', ' :') and before.rstrip().endswith(('"', "'")):
        before = before.rstrip()
        quote, before = before[-1], before[:-1]
    else:
        quote = None
    if quote:
        pattern = re.escape(quote) + r'[^' + re.escape(quote) + r']*$'
        key = re.search(pattern, before)
        lead = before[:key.start()] if key else ''
        lead = re.sub(r'\b[urbf]$', '', lead).rstrip()  # Python string prefixes
        delimiter = lead[-1:]
        if key and delimiter == ',' and len(before[key.start() + 1:].split()) > 5:
            return 0.0  # A sentence-like quotation, not a field name.
        if delimiter not in ('{', ',') and lead.strip():
            return 0.0
        # Estimates for the first, subsequent, and fragmentary field of an object.
        values = (6.0, 4.45, 3.2) if quote == '"' else (6.0, 4.0, 3.5)
        if token.startswith('\\'):
            values = (7.1, 5.4, 4.0)
        if token == ' :':
            values = (8.0, 7.0, 4.0)
        return values[0 if delimiter == '{' else 1 if delimiter == ',' else 2]
    if token == '?:':
        return 0.65
    if token not in (':', ' :'):
        return 0.0
    key = re.search(r'[\w$]+$', before)
    if not key:
        return 0.0
    lead = before[:key.start()].rstrip()
    delimiter = lead[-1:]
    line_key = bool(re.fullmatch(r'\s+[\w$]+', before.split('\n')[-1]))
    if '<style' in before and before.rfind('<style') > before.rfind('</style'):
        return 0.0
    if delimiter == '{':
        context = lead[:-1].rstrip()
        if context.endswith(('^', '_', ')')):
            return 0.0
        if re.search(r'\\(?:cite\w*|ref|eqref|label)(?:\[[^\]]*\])?$', context):
            return 0.0
        if re.search(r'\b(?:struct|interface|class|enum|impl)\s+[^{}]*$', context):
            return 0.0
        if not key.group().isascii() or (token == ' :' and len(key.group()) == 1):
            return 0.0
        if key.group().isdigit() and '\n' in before[len(lead):]:
            return 0.0
        if re.search(r'(?m)//[ \t]*[A-Z]+$', text):
            return 0.0
        return 5.5
    opened = open_bracket(lead)
    if delimiter == ',' and (
        opened == '{' or (line_key and opened not in ('(', '['))
    ):
        return 4.4
    return 0.6 if line_key and opened == '{' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (text + token)[-1600:]), response(token, text)

"""An opening-token signal, sustained while the prefix is one repeated token.

The amplitude is estimated from word frequency, capitalization, whitespace,
script/character shape, and a few familiar punctuation and word classes.
A different token ends the opening run; thereafter predict zero.
Exact, idiosyncratic token amplitudes are deliberately not modeled.
"""
import unicodedata
from wordfreq import zipf_frequency

READS = ()
AUXILIARIES = frozenset('''be am is are was were been being do does did
    done have has had having can could may might must shall should will
    would'''.split())
PRONOUNS = frozenset('''i me my mine myself you your yours yourself he him
    his himself she her hers herself it its itself we us our ours ourselves
    they them their theirs themselves'''.split())


def opening_value(text):
    if text == '<|im_start|>':
        return 4.64
    word = text.strip()
    if '\n' in text:
        return -0.4
    if not word:
        return 3.3 if len(text) == 1 else 6.0
    if word.isdigit():
        return -0.5
    frequency = zipf_frequency(word.lower(), 'en') if word.isalpha() else 0.0
    if len(word) == 1:
        if text.isascii():
            if word.isalpha():
                return 0.3 if text.startswith(' ') else -0.6
            if word == '.':
                return 3.2
            if word == ':':
                return 2.8
            if word == ';':
                return -5.7
            if word in ',#':
                return 0.1
            return 1.3
        if unicodedata.category(word)[0] in 'PS':
            return 2.7
        return 5.2 if frequency <= 1.5 else 1.4
    if frequency > 7.1:
        return -0.7
    if frequency > 6.2:
        if word.lower() in AUXILIARIES:
            return 2.5
        return -0.3 if word.lower() in PRONOUNS else 1.0
    if frequency <= 4.4:
        return 5.0 if word.istitle() else 3.85
    return 2.35 if word.islower() else 3.5


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = int(prefix.token_ids[-1])
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        return (doc, token, value, True), value
    _, first, value, opening = carry
    opening = opening and token == first
    return (doc, first, value, opening), value if opening else 0.0

programs.haiku:
"""Standalone space before a number, in running prose and dates.

In this tokenizer a number is written as separate digit tokens, so the space before a
number is its own token " ". This component is a detector for that space. It is positive
when the text so far is ordinary prose and a number is about to start: most strongly in
dates ("born October 16," or "on March 3," where a day or year comes next), and after
prepositions such as "in", "at", "since" or "around". It is weaker after labels such as
"Figure" or "Table", weakly positive after code symbols, near zero after a digit or an
indent, and negative after a line break, a quote, or an escaped newline in code.
"""

MONTHS = {
    "January", "February", "March", "April", "May", "June", "July", "August",
    "September", "October", "November", "December", "Jan", "Feb", "Mar", "Apr",
    "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec",
}
# Words after which a number is very likely: prepositions, "born", "the", "a".
NUMBER_CUES = {
    "in", "at", "around", "within", "born", "since", "after", "until", "over", "about",
    "between", "approximately", "least", "only", "than", "from", "for", "of", "on",
    "under", "into", "with", "the", "a",
}
# Words that introduce a label or an identifier, not a quantity.
LABEL_WORDS = {
    "Figure", "Table", "Section", "Step", "Line", "line", "Test", "code", "return",
    "section", "index", "node", "portion", "Example",
}
CODE_SYMBOLS = set("{}()[]<>=+-*/|&!#$%^~_;")
QUOTES = set("'\"`")
READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    if tokens[-1] != " " or len(tokens) < 2 or docs[-2] != docs[-1]:
        return None, 0.0
    before = tokens[-2]
    word = before.strip()
    # Only the last few tokens of this document count as context.
    recent = [
        tokens[i].strip()
        for i in range(max(0, len(tokens) - 6), len(tokens) - 1)
        if docs[i] == docs[-1]
    ]
    if "\n" in before:
        value = -0.4
    elif word == "":
        value = 0.0
    elif word == "n" and len(tokens) > 2 and "\\" in tokens[-3]:
        value = -2.0  # an escaped "\n" inside a code string
    elif "\\" in before:
        value = -1.0
    elif word in MONTHS:
        value = 1.1
    elif word in NUMBER_CUES:
        value = 1.4
    elif word in LABEL_WORDS:
        value = 0.5
    elif word.isalpha():
        value = 0.9
    elif word.isdigit():
        value = 0.15
    elif word in QUOTES:
        value = -0.7
    elif word == ",":
        value = 1.1
    elif word == ".":
        value = 0.75
    elif word == ":":
        value = 0.95
    elif word and all(c in CODE_SYMBOLS for c in word):
        value = 0.4
    else:
        value = 0.8
    # Inside a date ("March 3, " or "March "), a year or day is expected.
    if word not in MONTHS and any(x in MONTHS for x in recent):
        value += 1.0
    return None, value

programs.sol:
"""A partial approximation of the component's person-suffix response.

Tokens starting with 人 ('person') become more negative after a Chinese
stem or count. Grammatical continuations change the response's gain.
CC-CEDICT recognizes person compounds; collective words get a separate
small positive value. Double interpuncts have a positive response.
Other tokens are zero: rarer compound effects and background are omitted.
"""
from functools import lru_cache
import regex
import cedict

READS = ()
FUNCTION_CHARS = frozenset(
    '的了是在和与與为為以有无無不也都'
    '就而及但把被让讓给給于於对對这這那其此所之'
)
NUMERALS = frozenset('一二三四五六七八九十百千万萬亿億两兩俩倆')
JAPANESE_PARTICLES = frozenset('がはのもにとをで')
# Each pair is an offset and the gain for a preceding person-forming stem.
RESPONSE = {
    'bare': (-0.0202, -0.5074),
    'possessive': (0.1316, -0.9615),
    'all': (-2.3321, -1.5411),
    'plural': (0.3499, -2.5185),
    'japanese': (0.016, -0.6346),
    'lexical': (-0.243, -1.5448),
}

@lru_cache(maxsize=16384)
def context_strength(previous):
    if not previous:
        return 0.0
    c = previous[-1]
    if c.isdecimal() or c in NUMERALS:
        return 0.85
    if c in FUNCTION_CHARS:
        return 0.0
    if len(previous) == 1 and regex.fullmatch(r'\p{Script=Han}', c):
        return 1.0
    if len(previous) <= 3 and cedict.glosses(previous + '人'):
        return 0.7
    if c == '\ufffd':
        return 0.65
    return 0.15 if regex.fullmatch(r'\p{Script=Han}', c) else 0.0


def kind_of(text):
    if text == '人':
        return 'bare'
    if text == '人的':
        return 'possessive'
    if text == '人都':
        return 'all'
    if text in ('人们', '人們'):
        return 'plural'
    if len(text) == 2 and text[1] in JAPANESE_PARTICLES:
        return 'japanese'
    return 'lexical'


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if text == '··':
        return None, 0.95
    if not text.startswith('人'):
        return None, 0.0
    if text.startswith(('人民', '人工', '人员', '人員', '人类', '人類',
                        '人际', '人際', '人文', '人脸', '人臉',
                        '人数', '人次', '人均')):
        return None, 0.1
    previous = ''
    if (len(prefix.token_ids) > 1
            and prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    offset, gain = RESPONSE[kind_of(text)]
    return None, offset + gain * context_strength(previous)

"""Romance genitive ('of') constructions, in spelling and local grammar.

Detect contracted forms such as del, du, della and Portuguese do/da, or
an article/possessive after de/di/d'. Dictionary word frequencies identify
the surrounding language, separating these from English do and Nordic du.
Names and short pieces inside words get weaker values. German der has a
small baseline; unmatched tokens are zero.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('pt', 'en', 'it', 'es', 'fr', 'pl', 'tr', 'de',
             'sv', 'da', 'nb', 'cs', 'sk', 'vi')
NORDIC = {'sv', 'da', 'nb'}
FUSED = {'del': 5.5, 'della': 6.7, 'delle': 5.7, 'dei': 5.0,
         'dello': 8.5, 'degli': 6.0, 'dell': 8.6}
PORTUGUESE = set('do da dos das desse dessa desses dessas deste desta '
                 'destes destas dele dela deles delas dess dest'.split())
INDEFINITES = set('un una une unos unas um uma algum alguma'.split())
DETERMINERS = set('ce cet cette ces sa ses son su sus mi mis mon ma mes '
                   'nos vos leur leurs este esta estos estas ese esa esos esas '
                   'aquel aquella aquellos aquellas'.split())


@lru_cache(maxsize=40000)
def votes(word):
    frequencies = [zipf_frequency(word, lang) for lang in LANGUAGES]
    peak = max(frequencies)
    return [max(0., f - peak + 1.) if peak >= 3 else 0. for f in frequencies]


def language(text):
    # Sum votes for languages within one Zipf point of each word's peak.
    totals = [0.] * len(LANGUAGES)
    for word in re.findall(r'\b[^\W\d_]+\b', text[-160:].lower()):
        totals = [a + b for a, b in zip(totals, votes(word))]
    if not any(totals):
        return None
    return LANGUAGES[max(range(len(totals)), key=totals.__getitem__)]


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = token.strip().lstrip('-').lower()
    boundary = token[:1].isspace() or not tail or not tail[-1:].isalpha()
    genitive = re.search(r"\b(?:de|di|d['’])\s*$", tail.lower())
    lang = language(tail) if genitive or s in FUSED or s in (
        PORTUGUESE | {'du', 'des'}) else None
    value = 0.0
    if genitive:
        if s == 'la':
            value = 7.8 if lang == 'fr' else 6.5
        elif s == 'l' and token.strip() != 'L':
            value = 5.0 if lang == 'es' else 8.5
        elif s in {'los', 'las'}:
            value = 5.8 if s == 'los' else 4.7
        elif s in INDEFINITES:
            value = 3.8
        elif s in DETERMINERS:
            value = 3.0
    if s in {"'un", "'une", '’un', '’une'} and tail.lower().endswith('d'):
        value = 5.5
    if s in FUSED:
        value = FUSED[s] * (1.0 if token[:1].isspace() else 0.6)
        if lang in NORDIC and s in {'del', 'dei'}:
            value = 0.2
    elif s == 'du':
        value = 5.4 if lang == 'fr' else (-0.3 if lang in NORDIC else 1.8)
    elif s == 'des':
        value = 5.2 if lang == 'fr' else 1.3
    elif s in PORTUGUESE:
        value = (5.3 if s in {'dos', 'das'} else 6.8) if lang == 'pt' else 0.1
    elif s == 'der':
        value = 0.5
    if not boundary and tail.lower().endswith('d') and 'd' + s in FUSED:
        value = FUSED['d' + s] * 0.7
    if len(s) == 4 and s.endswith('del'):
        value = 4.0
    if token.strip().istitle() and len(s) > 1:
        value *= 0.5
    new_tail = '' if token == '<|endoftext|>' else (tail + token)[-240:]
    return (doc, new_tail), value

"""A pulse at a document's opening, lasting through identical opening tokens.

The pulse varies with the opening token's spelling: short title-cased words
and source-code import/package keywords are stronger, acronyms weaker.
Case and length groups approximate the remaining token-to-token variation.
After the opening run the prediction is zero. Token-specific differences
within these groups and later context effects are deliberately omitted.
"""
READS = ()

IMPORT_WORDS = {'import', 'using', 'from', 'namespace'}


def opening_strength(token):
    word = token.strip()
    if token == '<|im_start|>':
        return 3.34
    if token == 'package':
        return 15.45
    if token in IMPORT_WORDS:
        return 9.6
    if word == '0':
        return 0.05
    if word.isupper():
        return 1.87 if len(word) == 1 else 0.0
    if word.istitle():
        return 7.0 if len(word) <= 3 else 4.63
    if word.islower():
        return 3.70
    if not word:
        return 4.88
    return 2.90


def step(carry, prefix, upstream):
    token_id = prefix.token_ids[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        strength = opening_strength(prefix.token_strings[-1])
        carry = document, token_id, True, strength
    document, opening, repeating, strength = carry
    repeating = repeating and token_id == opening
    value = strength if repeating else 0.0
    return (document, opening, repeating, strength), value

"""A sparse mixture of lexical and spelling rules, not one semantic classifier.

Selected Chinese reach/haste spellings, Korean 급 and Vietnamese kịp receive
negative values. Two Thai tone marks after combining marks, and space-prefixed
split UTF-8 fragments, receive positive values; smart-quote bytes get extra
weight. Document starts, the 'Title:' header, leading carriage returns and
repeated middle dots have separate baselines. Irregular token-specific effects
are deliberately left unexplained rather than encoded in a large lookup table.
"""
import unicodedata

READS = ()
# The four smart quotation marks in the Windows-1252 encoding.
SMART_QUOTE_BYTES = {0x91, 0x92, 0x93, 0x94}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, previous, recent, only_cr = 0, b'', b'', True
    else:
        _, pos, previous, recent, only_cr = carry
    b = prefix.token_bytes[-1]
    s = b.decode('utf-8', 'replace')
    last = previous.decode('utf-8', 'replace')
    value = 0.001

    if pos == 0 and s.isascii():
        value = 0.20 if s.strip() else -0.05
        if s.strip().isdigit():
            value = 0.12
        if s.strip() == '"':
            value = 2.45 if s == '"' else 0.84
    if pos == 1 and last == 'Title' and s == ':':
        value = -8.9
    if b == b'\r' and only_cr:
        value = -3.5
    if s == '··':
        value = -0.36

