    if s == '及':
        value = -1.4
        if last.endswith(('可', '言', '谈', '談')):
            value = -3.4
        elif last.endswith('得'):
            value = -6.0
    elif s == '及时' or (s == '時' and last == '及'):
        value = -3.5
    elif s == '不及':
        value = -6.7
    elif '急' in s:
        value = -3.8 if s == '急' else -1.8
    elif s == '疾':
        value = -1.8
    elif s in ('紧', '緊'):
        value = -0.55
    elif s.strip() in ('급', 'kịp'):
        value = -2.3 if s.strip() == '급' else -3.6

