            if s == '้':
                value = 1.9 if last != 'ึ' else 1.2
            elif last != 'ึ':
                value = 1.0
    elif s in ('ื่', 'ื้'):
        value = 0.7

    if len(b) == 1 and 0x80 <= b[0] < 0xC0:
