        value = -1.2

    if low == 'too':
        value = -6.1
        if prev in BE:
            value = -7.8
        elif prev in INTENSIFIERS:
            value = -8.7
        elif prev == 'not':
            value = -5.7
        elif w[:1].isupper():
            value = -7.5
    elif word == 'trop':
        value = -6.0 if FRENCH.search(tail.lower()) else -0.5
    elif word in EXCESS:
        value = EXCESS[word]

    if len(text) >= 2 and not text.strip('·'):
        value = 1.6
    if position == 1 and previous == 'Title' and text == ':':
        value = -6.7
    if start and text in ('o', 'O'):
        value = -3.6 if text == 'o' else -1.9
    return (doc, recent, text, position + 1), value

"""A surface-form approximation, strongest at document openings.

Opening tokens usually have a negative background response, especially English
possessives, single-letter ASCII tokens, tabs and escaped whitespace. Certain
code/Markdown openings and the initial number 12 instead give positive spikes.
An initial run of identical tokens keeps its opening response. Away from the
opening, namespace/defmodule declarations and early Chinese chapter labels
are used; small, context-dependent activations are otherwise set to zero.
"""
import regex

READS = ()
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
CODE_OPENERS = {
    'namespace': 2.03,
    'module': 1.65,
    'int': 2.16,
    'string': 1.04,
    'function': 0.92,
    'class': 0.23,
    'var': 0.67,
    'def': -1.44,
    'import': 0.53,
    '#include': -0.53,
}


def opening(token):
    if token in CODE_OPENERS:
        return CODE_OPENERS[token]
    if token == '###':                 # Level-three Markdown heading.
        return 1.28
    if token == ' .':
        return 2.27
    if token == '··':                  # A dotted separator.
        return 0.715
    if token == '<|endoftext|>':
        return -2.17
    if token == '\t':
        return -2.69
    if token in {'\\n', '\\t'}:
        return -2.35
    if token.isspace():
        return -0.10
    word = token.strip()
    if word.lower() in POSSESSIVES:
        return -1.30 if token.startswith(' ') else -2.13
    if word.isascii() and word.isalpha() and len(word) == 1:
        return -0.45
    if word.isascii() and word.isdigit():
        return -0.53 if word in {'1', '2'} else -0.23
    if regex.fullmatch(r'\p{Script=Han}+', word):
        return -0.11
    return -0.22


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, repeated, line_blank = 0, '', True, True
    else:
        _, position, previous, repeated, line_blank = carry
        position += 1
        repeated = repeated and token == previous

    value = 0.0
    if repeated:
        value = opening(token)
    elif position == 1:
        if previous == '1' and token == '2':
            value = 3.92
        elif previous == 'Hy' and token == 'dro':
            value = 5.92
        elif previous == '<' and token == 'filename':
            value = 2.07
        elif previous == '(function' and token == ' ()':
            value = 2.37
    if token == 'namespace' and not repeated and line_blank:
        value = 1.3 if position < 4 else 0.65
    if token == 'module' and previous == 'def':
        value = 0.94
    if token == '章' and position < 50 and previous.strip().isnumeric():
        value = 0.8

    if '\n' in token:
        line_blank = not token.rsplit('\n', 1)[-1].strip()
    else:
        line_blank = line_blank and not token.strip()
    return (doc, position, token, repeated, line_blank), value

"""A text-layout approximation of an early-layer activation.

Negative pulses mark another quoted object field, a title/body break, or a
heading after unfinished prose.  Document-initial typography, boundary markers,
and English articles have separate responses.  Most other text receives zero;
the remaining word-specific variation is not modeled.
