import re

READS = ()


def initial(token):
    """Opening text, before any preceding text is available."""
    if token == '<|endoftext|>':
        return 3.84
    if token == '<|im_start|>':
        return -0.39
    if token.isspace():
        if token == ' ':
            return 0.04
        if '\n' in token and (token[0] in ' \t\r'):
            return 1.5
        if token[0] == '\n':
            return 0.45 if len(token) == 1 else 0.25
        if token == ' ' * len(token) and len(token) >= 3:
            return 1.5 if len(token) % 4 == 3 else 0.7
        return 0.27
    s = token.lstrip()
    if s.lower() == 'an':
        return 1.8 if token.startswith(' ') or s.istitle() else 0.85
    if s.lower() == 'a':
        return 0.65 if token.startswith(' ') and s.islower() else 0.44
    if s.lower() == 'the':
        return 0.6 if token.startswith(' ') else 0.04
    if s == '#':
        return 0.28
    if s.startswith(('"""', "'''")):
        return -0.6
    if s.startswith(('"', '“', '‘', '「', '《')):
        return 1.6 if len(s) == 1 else 1.3
    if s.startswith("'"):
        return 0.55 if token.startswith(' ') else 0.25
    if s == '<!':
        return 5.4
    if s.startswith('<?') or s == '<':
        return -1.0
    if s == '>':
        return 0.7
    if s and all(c in '#`*_' for c in s):
        return -0.6 if not s.startswith('```') else -1.5
    if s.startswith('//'):
        return -0.75
    if s == '\\':
        return -0.12 if token.startswith(' ') else -1.3
    if s == '\\n':
        return 0.7
    if s and set(s) == {'^'}:
        return -0.56 * len(s)
    if s and set(s) == {'·'}:
        return -0.82 * len(s)
    if token.isdigit():
        return 0.12
    if s.isascii() and s.isalpha():
        if token.startswith(' '):
            return 0.1
        return -0.2 if s.islower() else -0.1
    return 0.0


def unfinished_block(text):
    return ('\n' not in text and len(text.split()) >= 8
            and text[-1:].isalnum())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, first_line, tail, opening = 0, True, '', token
    else:
        _, position, first_line, tail, opening = carry
        position += 1
    value = 0.0

    if position == 0 or (opening is not None and token == opening):
        value = initial(token)
    elif token.replace('\\', '') in (' "', " '"):
