            value = -0.65 if token.endswith('\n\n') else -0.3
        elif heading and token == '\n\n':
            value = -0.2 if first_line else -0.1
        elif (token == '\n\n' and '\n\n### ' in tail
              and unfinished_block(line)):
            value = -0.25
        elif token == ' (\n' and tail.rstrip().endswith('import'):
            value = 0.55
    elif token == '</think>':
        value = -0.18

    if token != opening:
        opening = None
    first_line = first_line and '\n' not in token
    tail = (tail + token)[-500:]
    return (doc, position, first_line, tail, opening), value

"""Approximate a sparse mixture dominated by asterisk typography.

Bare line-leading stars and separately space-indented comment margins usually
get negative values. Document position, token boundaries, escaped newlines,
and comment delimiters modify these values; some forms are weakly positive.
Secondary rules recognize police words, documentation metadata, coding-cookie
markers, and selected Java namespaces. Unmodeled tokens receive zero.
Only a short text suffix and document position are carried between tokens.
"""
import math
import re

READS = ()


def star_value(s, tail, position, previous):
    word = s.strip()
    leading_space = s.startswith(' ')
    normalized = tail.replace('\\n', '\n')
    line = normalized.rsplit('\n', 1)[-1]
    at_margin = not line.strip()
    space_indent = bool(line) and not line.strip(' ')
    escaped_break = tail.rfind('\\n') > tail.rfind('\n')
    comment_first = normalized.rstrip().endswith(('/*', '/**'))

    if word == '-*-':  # Emacs-style coding declaration in a source header.
        return 2.0 if tail.rstrip().endswith(('#', '//')) else 0.0
    if len(word) >= 5 and not word.rstrip('/').strip('*'):
        return -0.6 if leading_space else -1.2
    if word.startswith('.*') and ';' in word:
        return -1.0
    if word.startswith('*/'):
        if leading_space:
            return -0.15 if at_margin else 0.1
        return -1.8 if at_margin else -0.5
    if not word.startswith('*'):
        return 0.0
    if any(c.isalpha() for c in word):
        return -0.5 if at_margin else 0.0
    if word.startswith('**'):
        if position == 0:
            return -1.0
        if at_margin and comment_first:
            return -0.7
        return -0.3 if at_margin else -0.05
    if position == 0 and word == '*':
        return 1.41 if leading_space else 0.66
    if at_margin:
        if position < 4 and comment_first and not leading_space:
            return -12.5
        early = math.exp(-position / 40.0)
        if leading_space:
            if comment_first and '\n' in s:
                return -1.8
            if '\n' in previous:
                return 0.05 if '\n' in s else 0.22
            if space_indent:
                return -0.65 - 0.5 * early - 1.15 * comment_first
            if escaped_break:
                return -0.45
            return -0.18 if '\t' in line else 0.22
        value = -0.6 if escaped_break else -1.4 - 1.7 * early
        return value * (0.6 if '\n' in s else 1.0)
    if leading_space:
        aligned = bool(previous) and not previous.strip(' ')
        return -0.45 if aligned else -0.16
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, tail = 0, ''
    else:
        _, position, tail = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    value = 0.0
    if '*' in s:
        previous = prefix.token_strings[-2] if position else ''
        value = star_value(s, tail, position, previous)
    elif word.casefold() == 'police':
        value = -3.0 if re.search(r'\bstate\s*$', tail, re.I) else -1.0
    elif word == '警':
        value = -3.8
    elif word == '警察':
        value = -2.4
    elif tail.rstrip().endswith('@') and re.search(
        r'(?:^|[*/\n])\s*@\s*$', tail
    ):
        # Familiar metadata fields in documentation comments.
        if word == 'author':
            value = -1.4
        elif word in ('date', 'version'):
            value = -3.2 if word == 'date' else -2.3
    elif tail.endswith('java'):
        # These are named Java namespaces, not arbitrary vocabulary entries.
        if word in ('.io', '.util'):
            value = 2.45 if word == '.io' else 1.05
        elif word in ('.stream', '.time'):
            value = -2.4 if word == '.time' else -1.0
    elif word == '.stream' and tail.endswith('.util'):
        value = -0.9
    return (document, position + 1, (tail + s)[-200:]), float(value)

programs.haiku:
"""Layer-1 MLP down_proj, component 478: a sparse 'markdown / doc-comment bullet' detector.

Plain-language summary: the component is mostly silent. It goes negative on a bare
asterisk "*" that starts a line (a Markdown bullet, or the leading " * " of a
/** ... */ doc comment), and more weakly on any other asterisk. It is also strongly
negative on a few Chinese/English police-and-exam words, and mildly positive on
Java/URL package-name pieces such as ".io", ".util", "api", "images".
Everything else is predicted as 0 (the average).
"""

READS = ()

LINE_START_STAR = -0.5    # "*" that begins a line (after optional indentation)
OTHER_STAR = -0.1         # "*" elsewhere, e.g. "a * b" or "**bold**"
POLICE_EXAM = {"police", " police", "Police", " Police", "警", "警察", "考试", "警告"}
PACKAGE_PIECES = {".io", ".util", ".os", ".support", ".stream", "api", "images", ".URL"}
POLICE_VALUE = -1.0
PACKAGE_VALUE = 0.12


def _starts_line(prefix):
    """True if the newest token is preceded, on its line, only by whitespace."""
    tokens = prefix.token_strings
    docs = prefix.document_ids
    for i in range(len(tokens) - 2, -1, -1):
        if docs[i] != docs[-1]:
            return False
        if "\n" in tokens[i]:
            return True
        if tokens[i].strip():
            return False
    return False  # start of the row: no line before it


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    stripped = token.strip()
    if stripped == "*":
        value = LINE_START_STAR if _starts_line(prefix) else OTHER_STAR
    elif token in POLICE_EXAM:
        value = POLICE_VALUE
    elif token in PACKAGE_PIECES:
        value = PACKAGE_VALUE
    else:
        value = 0.0
    return carry, float(value)

"""Era words. The component goes negative on the word that names a historical era or
a long span of time: strongly on "century", "classical", "ancient", "medieval", "antique"
(and their Romance and Chinese/Japanese forms, e.g. antigo, ancienne, 古代), more weakly
on "past", "ago", "ages", "modern", "historic", "historical", and on "day", "times",
"years", "now", "time" when they close a time-span phrase ("present day", "modern times",
"our time", "over time"). Other time words (era, decade, present, before) stay near zero.

Words are rebuilt from the tokens typed so far, so a word split across tokens
("Twentieth-Cent" + "ury") fires on its last piece."""
import re

READS = ()

STRONG_STEMS = ("centur", "classic", "ancient", "antiq", "medieval", "ancien")
STRONG_WORDS = {"antigo", "antiga", "antiguo", "antigua"}
WEAK_WORDS = {"past", "ago", "ages", "modern", "historic", "historical"}
SPAN_WORDS = {"day", "times", "years", "now", "time"}
SPAN_BEFORE = {"present", "modern", "recent", "our", "over", "all", "middle"}
CJK_STRONG = {"古", "古代", "古典", "昔", "世纪"}
STRONG_VALUE, WEAK_VALUE, SPAN_VALUE, CJK_VALUE = -4.4, -0.8, -2.0, -3.6

WORD_END = re.compile(r"[A-Za-z\-]+$")  # letters and hyphens at the end of a token


def step(carry, prefix, upstream):
    """carry: (the word being typed, the whole word before it), or None."""
    text = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    current, before = ("", "") if new_doc or carry is None else carry
    if text.strip() in CJK_STRONG:
        return ("", current), CJK_VALUE
    end = WORD_END.search(text)
    if end is None:
        return ("", current), 0.0
    if (text[:1].isalpha() or text[:1] == "-") and current:
        word = current + end.group(0).lower()  # the word continues from the last token
    else:
        before = current if current else before
        word = end.group(0).lower()
    if any(s in word for s in STRONG_STEMS) or word in STRONG_WORDS:
        value = STRONG_VALUE
    elif word == "ages" and before == "middle":
        value = STRONG_VALUE
    elif word in WEAK_WORDS:
        value = WEAK_VALUE
    elif word in SPAN_WORDS and before in SPAN_BEFORE:
        value = SPAN_VALUE
    else:
        value = 0.0
    return (word, before), value

programs.sol:
"""Approximate the negative response to letter-by-letter writing.

The response grows through runs of isolated Latin letters. NUL-interleaved
letters and fullwidth Latin forms are also negative, especially vowels.
Middle dots after punctuation get a smaller negative value. Ordinary text
is near zero, with a small positive offset for an initial alphabetic token.
This leaves weak, vocabulary-specific fluctuations unexplained.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()


@lru_cache(maxsize=32768)
def shape(s):
    stripped = s.strip()
    word = ud.normalize('NFKC', stripped)
    length = len(word) if word.isascii() and word.isalpha() else 0
    single = length == 1
    punctuation = bool(stripped) and all(
        ud.category(c)[0] in 'PS' for c in stripped)
    fullwidth = any(
        'FULLWIDTH LATIN' in ud.name(c, '') for c in stripped)
    dots = bool(stripped) and set(stripped) <= set('·・‧')
    return word, length, single, punctuation, fullwidth, dots


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, run = '', 0
    else:
        _, previous, run = carry
    word, length, single, punctuation, fullwidth, dots = shape(s)
    _, _, prev_single, prev_punctuation, _, _ = shape(previous)
    spaced_previous = prev_single and previous.startswith(' ')
    value = 0.0

    if previous == '\x00':
        if length:
            if word.isupper():
                value = -0.55
            else:
                value = -2.29 if single and word in 'aeiou' else -1.61
        else:
            value = -0.065
    elif fullwidth:
        value = -2.3 if single and word in 'aeiou' else -0.75
    elif single and spaced_previous:
        strength = min(1.0, max(0.0, (run - 1) / 6))
        if word.isupper():
            amplitude = 1.3
        else:
            amplitude = 2.0 if word in 'aeiou' else 1.2
        value = -strength * amplitude
    elif dots and prev_punctuation:
        value = -0.39
    elif s == '\x00' and run >= 4:
        value = -0.10
    elif first and length >= 3 and not s.startswith(' '):
        value = 0.12

    # Separators preserve the run; ordinary multi-letter pieces break it.
    if single:
        run = min(run + 1, 8)
    elif length or not (punctuation or not s.strip() or s == '\x00'):
        run = 0
    return (doc, s, run), value

"""Approximate a response to the end of a single-spaced block.

A blank line is stronger after recent ordinary line breaks than after other
blank lines. Their recency difference, over a hundred-token horizon, measures
this change of spacing. Punctuation changes the baseline and response size;
blank lines beside reasoning-block tags have explicit amplitudes.

Secondary rules cover document starts, C include directives, shell EOF markers,
chat delimiters and repeated middle dots. Other positions are near zero.
These formatting rules leave much token-specific activation unexplained.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
