        if n >= 3:
            value = 0.29 + 0.34 * novelty
        elif not punctuation:
            value = 0.15 + 1.12 * novelty
        elif not punctuation.strip():
            value = -0.03 + 0.80 * novelty
        elif punctuation.endswith(','):
            value = -0.076 + 0.87 * novelty
        elif punctuation.endswith(':'):
            value = 0.81 * novelty
        elif punctuation.endswith(('.', '?', '!')):
            value = 0.01 + 0.94 * novelty
        elif punctuation.endswith('}'):
            value = 0.11 + 0.16 * novelty
        elif punctuation.endswith(';'):
            value = 0.17 + 0.30 * novelty
        else:
            value = 0.12 + 0.68 * novelty
        if previous == '<think>':
            value = 0.98
        elif previous == '</think>':
            value = 0.60
