        value = -0.70
    elif token == '<think>':
        value = -0.10
    elif token == '</think>':
        value = 0.125
    elif token == '<|im_start|>':
        value = 0.21 if position == 0 else 0.09
    elif token in ('<tool_call>', '<tool_response>'):
        value = 0.07
    elif n:
        value = -0.02
    if n:
        last_line = position
    if blank:
        last_blank = position
    return (doc, position + 1, last_line, last_blank, token), float(value)

"""Negative pulses at document/row starts, with weaker Unix-path responses.

Onset size depends on whitespace, punctuation, script and grammatical class.
Unclassified ASCII words get stronger pulses when longer or capitalized, and
weaker ones with a leading space. Away from starts, only selected directory
names following a slash, and /local following usr, receive negative values.
This captures the onset pattern, not exact word-specific sizes or background
fluctuations; a token lookup would add those sizes rather than a new rule.
"""
import regex

READS = ()
WORD_CLASSES = (
    (-5.5, frozenset('a an the'.split())),  # Articles
    (-4.0, frozenset('''in on at by for from of to with as into onto upon about
        over under between through during without within and or but if because
        while although unless nor'''.split())),
    (-7.0, frozenset('''i you he she it we they me him her us them who what which
        my your his its our their'''.split())),
    (-6.4, frozenset('this that these those'.split())),
    (-4.9, frozenset('''is are am was were be been being do does did have has had
        can could may might shall should will would must'''.split())),
    (-3.6, frozenset('''package import using include define ifdef endif pragma
        theorem lemma namespace class struct enum def function return public
        private static void const let var int float bool string type module
        open use fn impl export'''.split())),
