ROOT_DIRECTORIES = frozenset('workspace usr opt root tmp home etc var'.split())


def onset(token):
    s = token.strip()
    if token.startswith('<|'):
        return -4.2
    if not s:
        if token == ' ':
            return -1.1
        if '\t' in token:
            return -7.2 if token == '\t' else -4.5
        return -3.2 if '\n' in token or '\r' in token else -4.8
