            return -4.6 if '\n' in token else -1.7
        if s == ')':
            return -11.6 if token == ')' else -4.2
        if s == ',':
            return -3.3
        if s == ':':
            return -1.8
        if all(c in '([{<' for c in s):
            return -2.9
        if all(c in ')]}>' for c in s):
            return -6.4
        if s in ('"', "'", '`'):
            return -3.0 if token.startswith(' ') else -9.4
        if s in '$€£¥₹' and len(s) == 1:
            return -3.5 if token.startswith(' ') else -8.2
        if s.startswith('#'):
            return -3.0
        if s in ('-', '--', '—', '–', '_'):
            return -2.7
        return -3.9
