DOT_RUN = "··"
PATH_PIECES = {"workspace", "/workspace", "usr", "tmp", "opt", "root", "/local", "^^^^"}


def is_word(text):
    return text.isascii() and text.isalpha()


def doc_start_value(token):
    word = is_word(token)
    if not word:
        return -3.5
    value = -5.5
