"""A formatting heuristic, leaving most word-specific variation unmodeled.

Document-initial whitespace, escapes and code markers have positive levels.
Keep those levels while the document prefix repeats just one token. Otherwise
use small syntax defaults, with negative corrections for recurring CSV missing
values, comma-prefixed parameters and spaced underscores. Consecutive lowercase
single-word anagrams depress word pieces and, increasingly, their newlines.
State resets at each document boundary; only a 128-character suffix and short
line summaries are retained.
"""
READS = ()


def token_level(s, initial):
    if initial:
        if len(s) >= 2 and not s.strip('·'):
            return 2.54
        if s in {'\\n', '\\t', '\\"'}:
            return {'\\n': 2.54, '\\t': 2.16, '\\"': 2.28}[s]
        if len(s) >= 4 and not s.strip('\\'):
            return 2.07
        if s and not s.strip('\t'):
            return 2.07 if len(s) == 1 else 0.85
        if '\xa0' in s and s.isspace():
            return 1.28
        if s and not s.strip(' '):
            return 0.15 if len(s) == 1 else 0.27
        if s and not s.strip('\r\n'):
            return 0.31
        if s.startswith('//'):
            return 3.94 if s == '//\n' else 0.24
        if s.startswith('/*'):
            return 1.3
        if s.startswith('#!'):
            return 0.9
        if s in {'int', 'def'}:
            return 2.43
        if s in {'const', 'var', 'let', 'class', 'function', 'import', 'package'}:
            return 0.8
        if s == '**':
            return 2.83
        if s.startswith('```'):
            return 1.56
        if s.isdecimal():
            return 0.07
        if s in {'{', ' {', '{\n', ' {\n'}:
            return 0.58
        if s in {',', '.', ';', ':', ')'}:
            return {',': 0.14, '.': 0.14, ';': 0.57, ':': -0.23, ')': 0.21}[s]
        if s.startswith('#'):
            return 0.65
        if s.islower():
            if s.startswith('<'):
                return 0.31
            if len(s) == 1:
                return 0.20
            return -0.11 if s.isalpha() else -0.018
        if s.lstrip()[:1].isupper():
            return 0.15 if s.startswith(' ') else 0.267
        return 0.12

    if s.startswith('\\x'):
        return -0.2 if s[2:3].lower() in 'abc' and len(s) > 2 else -0.03
    if s == ',@':
        return -0.08  # comma-prefixed parameter or annotation
    if s in {',n', ',None', ',nan', ',NaN', ',null', ',NULL'}:
        return -0.23  # delimiter followed by a missing-value marker
    if s == '+\n':
        return -0.18  # an empty added line in a diff
    if s in {'\r', '\x00', '\x0c'}:
        return {'\r': -0.15, '\x00': 0.11, '\x0c': 0.38}[s]
    if s.startswith('\t') and s[1:] and not s[1:].strip(' '):
        return min(0.1, 0.045 + 0.004 * len(s))
    if s and not s.strip(' '):
        return -0.06 if 4 <= len(s) <= 8 else -0.006
    if s and not s.strip('_'):
        return 0.03 if len(s) == 1 else -0.05
    if s == '://':
        return -0.1
    if s in {'/*', '/*\n', '/**', '/**\n'}:
        return 0.043
    if s == "'":
        return -0.025
    if s == '<|im_start|>':
        return 0.05
    return -0.003


def signature(line):
    if line and 5 <= len(line) <= 32 and line.isalpha() and line.islower():
        return ''.join(sorted(line))
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, '', '', '', 0)
    _, first, uniform, recent, line, last_word, run = carry
    # The initial level persists until a contrasting token appears.
    uniform = uniform and token == first
    value = token_level(s, uniform)
    if not uniform:
        if s == ',n':
            value = -0.15 - 0.13 * min(recent.count('nan'), 2.3)
        elif s == ',None':
            value = -0.04 - 0.08 * min(recent.count(',None'), 4)
        elif s == ',@':
            value = -0.08 - 0.06 * min(recent.count(',@'), 4)
        elif s == ' _':
            value = 0.10 - 0.04 * min(recent.count(' _'), 7)
    if run and line is not None and s.isalpha() and s.islower():
        value -= 0.1
    # Compare completed one-word lines by their sorted letters.
    for i, part in enumerate(s.split('\n')):
        if i:
            sig = signature(line)
            matched = sig is not None and sig == signature(last_word)
            run = run + 1 if matched and (line != last_word or run) else 0
            if run and s == '\n':
                value = -0.17 - 0.025 * min(run, 7)
            last_word, line = line, ''
        if line is not None:
            line += part
            if len(line) > 32 or (line and not (line.isalpha() and line.islower())):
                line = None
    carry = (doc, first, uniform, (recent + s)[-128:], line, last_word, run)
    return carry, float(value)

