"""Candidate 1: long unbroken hash-like runs of hex / alphanumeric characters."""
import string

READS = ()

HEX = set("0123456789abcdefABCDEF")
ALNUM = set(string.ascii_letters + string.digits)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        doc_start, hex_run, alnum_run = True, 0, 0
    else:
        doc_start, hex_run, alnum_run = False, carry[1], carry[2]
    for ch in token:
        hex_run = hex_run + 1 if ch in HEX else 0
        alnum_run = alnum_run + 1 if ch in ALNUM else 0
