"""A conservative approximation of Indonesian word-fragment and formatting responses.

Completed words provide language evidence: words more frequent in Indonesian than
English raise it, and English words lower it. In Indonesian-looking text, word
starts, capitals and short consonant fragments receive positive responses; common
function words and productive affixes reduce them. Punctuation has separate values.
A few independent rules handle initial Title labels, acronyms and dot leaders.
This does not attempt to memorize individual names or lexical token pairs.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
FUNCTION_WORDS = frozenset(
    'yang dengan untuk tidak dalam adalah oleh pada ini itu dari akan juga '
    'sebagai atau sudah saya mereka kita karena menjadi tersebut kepada '
    'dapat harus di dan ke'.split()
)

@lru_cache(maxsize=65536)
def frequencies(word):
    return zipf_frequency(word, 'en'), zipf_frequency(word, 'id')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0.0, '', '', 0)
    _, evidence, partial, recent, position = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    low = word.lower()
    starts = (bool(token[:1].isspace()) or not recent
              or not recent[-1:].isalpha())

    # Only completed, already visible words contribute language evidence.
    for part in re.findall(r'[A-Za-z]+|[^A-Za-z]+', token):
        if part.isascii() and part.isalpha():
            partial += part.lower()
        elif partial:
            en, ind = frequencies(partial)
            evidence *= 0.85
            if len(partial) >= 3 and ind >= 3 and ind - en >= 1:
                evidence += min(2.0, ind - en)
            elif en >= 3 and en - ind >= 1:
                evidence = max(0.0, evidence - 1.0)
            partial = ''
    language = min(1.0, max(0.0, (evidence - 2.0) / 3.0))

    value = -0.077 if position == 0 else 0.0
    if token == ':' and position == 1 and recent == 'Title':
        value += 2.91
    if word and set(word) == {'·'} and recent.endswith('·'):
        value -= 1.08
    if token.startswith(')') and re.search(r'\s\([A-Z -]{2,16}$', recent):
        value += 0.074
    if token == '.com':
        value += 0.034

    response = 0.0
    if word.isascii() and word.isalpha():
        response = 0.59 if starts else 0.31
        if starts and word[0].isupper():
            response += 0.63
        if starts and len(word) == 1 and low not in 'aeiou':
            response += 0.57
        if low in FUNCTION_WORDS:
            response -= 0.46
        en, ind = frequencies(low)
        response += 0.01 * max(0.0, en - 3) - 0.03 * max(0.0, ind - 3)
        if starts and low.startswith(('me', 'peng', 'peny', 'pem', 'pen')):
            response -= 0.50
        if not starts and low in {'kan', 'nya', 'an'}:
            response -= 0.16
        if not starts and low == 'o':
            response += 2.04
    elif not word.isdigit():
        response = 0.32
        if token == ',':
            response += 0.075
        if token.startswith('.'):
            response -= 0.11
        if word == '(':
            response += 0.54
        if token.startswith(')'):
            response += 0.97
        if token == '/':
            response += 1.89
        if token.startswith(':'):
            response -= 1.11
    value += language * response
    carry = (doc, evidence, partial[-60:], (recent + token)[-100:], position + 1)
    return carry, float(value)

"""Approximate speaker/author-label boundaries and neighboring metadata.

The strongest cues are chat-header newlines, reporting words after short
name-like labels, and comment dates after an attribution dash.  Name-like
standalone lines use English word rarity, not a list of particular people.
Version patch digits and a few negative formatting cues are separate rules.
All context and token-position counts restart at document boundaries.
"""
import calendar
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
ABBREVIATIONS = set(calendar.month_abbr[1:])
MONTHS = ABBREVIATIONS | set(calendar.month_name[1:])
REPORTING = {'said', 'says', 'wrote', 'writes', 'posted', 'replied'}
PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}
PROFILE_FIELDS = {'Joined': 1.37, 'Posts': 0.56, 'Location': 1.07}


@lru_cache(maxsize=10000)
def rare(word):
    return bool(word) and zipf_frequency(word, 'en') < 2.5


def predict(s, context, age):
    word = s.strip()
    line = context.rsplit('\n', 1)[-1]
    if s == '\n':
        if context.endswith('<|im_start|>user'):
            return 0.21 if age < 4 else 1.42 + 0.07 * math.log1p(age)
        if context.endswith('<|im_start|>assistant'):
            return 0.01 if age < 4 else -0.07 + 0.128 * math.log1p(age)
