        if explicit_author:
            return 5.2 if abbreviated else 4.9
        if re.search(r'[–—]\s*\S+(?:\s+\S+){0,3}$', line):
            return 4.3 if abbreviated else 0.0
        return 0.23 if abbreviated else 0.0

