    handle = bool(name) and any(c.isalpha() for c in name) and (
        '_' in name or any(c.isdigit() for c in name) or
        any(c.isupper() for c in name[1:]))
    short_label = (0 < len(line.strip()) < 60 and
                   len(line.split()) < 4 and
                   bool(re.search(r'[A-Za-z]', line)) and
                   line.strip().lower() not in PRONOUNS)
    if word in REPORTING and s.startswith(' '):
        if word == 'wrote':
            return 4.3 if short_label else 0.12
        if short_label:
            return 0.89 + (3.15 if rare(name) else 0.0)
        return 0.25 if title_case or handle else 0.0
