        value = 0.1 if short_label and (title_case or handle) else 0.0
        label = re.fullmatch(
            r'(?:#+\s*|[•*]\s*|\d+\.\s*)?([A-Za-z][A-Za-z0-9_-]{2,29})',
            line.strip())
        if label and rare(label.group(1)):
            value += 0.33
