            value = -2.0
        else:
            value = -1.5 if history.endswith(('\n', '>')) else -0.2
    elif w == '«':
        value = -2.6 if '#####' in history[-150:] else -0.1
    elif w and set(w) == {'·'} and len(w) > 1 and history.endswith('·'):
        value = -1.15
    elif w and set(w) == {'█'} and len(w) > 1:
        value = -2.7
    elif w == '×' and '\n' in s:
        value = -3.8
    elif s == '\x0c':
        value = -0.75 if '          ' in history[-120:] else -0.2

    # Read the completed symbol when its UTF-8 bytes span tokens.
    if '\ufffd' in s:
        completed = raw.decode('utf-8', 'ignore')
        if completed.endswith(('✖', '✗')):
            value = -0.8
        elif completed.endswith('‹'):
            value = -0.7
        elif completed.endswith('▸'):
            value = -2.3
        elif completed.endswith('▼'):
            non_latin = any(c.isalpha() and not c.isascii()
                            for c in history[-40:])
            value = 0.0 if non_latin else -4.0

    if w == '»' and '\n' in s:
        value *= 0.25

    if re.search(r'\*\s*[@\\]$', history[-40:]):
        if w in {'see', 'internal', 'static', 'details'}:
            value = 0.85 if w == 'see' else 1.5
        elif w in {'file', 'category', 'generated', 'desc', 'sa'}:
            value = 0.6
    line = history.rsplit('\n', 1)[-1]
    if line.strip() == '*' and w == '<':
        value = 1.1 if line == ' *' else 0.2
    if line.strip() == '* <' and w == 'p':
        value = 1.3 if line == ' * <' else 0.25
    if position < 8 and re.search(r'/\*\*?\s*\n\s*\*$', history):
        if w in {'This', 'To', 'generated'}:
            value = {'This': 2.5, 'To': 4.4, 'generated': 2.1}[w]
    if s == 'issue' and history.endswith('<issue_start><'):
        value = -1.2

    opened = max(0, opened + s.count('«') - s.count('»'))
    history = (history + s)[-500:]
    return (doc, history, opened, position + 1, raw[-4:]), float(value)

"""Approximate an 'of'/genitive-marker response, especially French de/d' and Italian di.

Recent dictionary word frequencies blend language-specific responses: Dutch de
and Indonesian di behave differently from Romance genitive markers. English
fixed phrases, spelling, case and token boundaries adjust the response. A few
other genitive forms have fixed levels; unrecognized tokens receive zero.
History is bounded to 300 characters and resets at document boundaries.
"""
import re
from math import exp
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Language: response to de, di, and a separate d (usually an elided de).
LEVELS = {
    'en': (1.8, 0.1, 0.05),
    'fr': (4.4, 0.9, 5.3),
    'it': (2.5, 4.5, 3.8),
    'es': (2.4, -0.65, 0.65),
    'pt': (2.7, 0.2, 0.5),
    'ro': (4.2, 1.0, 0.3),
    'nl': (-0.55, -2.0, -0.1),
    'de': (2.6, -0.4, 0.25),
    'sv': (-0.6, -0.5, -0.1),
    'nb': (-0.6, -1.5, -0.1),
    'da': (-0.2, -0.5, -0.1),
    'tr': (-0.4, -1.0, -0.2),
    'hu': (0.0, -1.0, 0.0),
    'id': (0.0, -0.5, 0.0),
}
LANGUAGES = tuple(LEVELS)

@lru_cache(maxsize=50000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language_response(text, column):
    local_weight = 0.0 if column == 1 else 0.5
    words = [w for w in re.findall(r'[^\W\d_]+', text.lower())
             if len(w) > 1][-12:]
    if not words:
        return 'en', LEVELS['en'][column]
    scores = [0.0] * len(LANGUAGES)
    total = 0.0
    for age, word in enumerate(reversed(words)):
        weight = 0.82 ** age
        total += weight
        for j, freq in enumerate(frequencies(word)):
            scores[j] += weight * freq
    last = frequencies(words[-1])
    scores = [s / total + local_weight * f for s, f in zip(scores, last)]
    best = max(scores)
    temperature = 0.4 if column == 2 else 0.2
    weights = [exp((s - best) / temperature) for s in scores]
    value = sum(w * LEVELS[l][column] for w, l in zip(weights, LANGUAGES))
    return LANGUAGES[scores.index(best)], value / sum(weights)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip(' _-./')
    low = word.lower()
    value = 0.0

    if low == 'of':
        case_bonus = 0.25 if word == 'Of' else 0.1 if word == 'OF' else 0
        value = 0.88 + case_bonus
        prior = re.findall(r'[^\W\d_]+', text.lower())
        prior = prior[-1] if prior else ''
        if prior in {'instead', 'out', 'think', 'thinking'}:
            value = 0.24
        elif prior in {'number', 'sum'}:
            value = 0.34
        elif prior in {'amount', 'lot', 'kind', 'terms', 'length', 'end'}:
            value = 0.59
        elif prior == 'because':
            value = 0.45
        elif prior in {'one', 'instance'}:
            value = 1.18
        elif text.rstrip().endswith(','):
            value = 1.43
    elif low in {'de', 'di', 'd'}:
        boundary = (token[:1].isspace() or not text or
                    not text[-1].isalpha() or token[:1] in '_-./')
        if low == 'd' and not token[:1].isspace():
            boundary = False
            value = 0.05
        if boundary:
            column = {'de': 0, 'di': 1, 'd': 2}[low]
            lang, value = language_response(text, column)
            if low == 'de' and word != 'de':
                if lang == 'en':
                    value = 0.65 if word.isupper() else 1.1
                elif lang == 'de':
                    value = 0.5
                elif word.isupper():
                    value += 0.7
                elif lang in {'es', 'pt'}:
                    value += 0.6
            if low == 'di' and word != 'di':
                value *= 0.15
            if low == 'd' and word != 'd':
                value *= 0.15
            if token[:1] in '_-':
                value *= 0.65
            elif token[:1] in './':
                value *= 0.25
    elif token in {"'", '’'} and previous.strip().lower() == 'd':
        # Exclude quoted character literals such as 'd'.
        value = 0.0 if text[-2:-1] in {"'", '"', '`'} else 4.7
        if previous == 'D':
            value = 1.0
    elif low == 'von':
        value = 1.0
    elif low == 'van':
        value = 0.75 if word == 'van' and token.startswith(' ') else 0.25
    elif token == 'の':
        value = 0.56
    elif token.strip() == '의':
        value = 1.2
    elif token.strip() == '的':
        value = 0.11
    elif low in {'typeof', 'instanceof'}:
        value = 1.05

    return (doc, (text + token)[-300:], token), float(value)

"""Recognize local digit and letter patterns, rather than word meanings.

The main negative signals are a three-digit window beginning in 1 and a
short spelling that repeats an l-like consonant.  The decimal window
100 has the opposite sign.  Coefficients describe sensitivity to decimal
digits, not numerical magnitude.  Separated repetitions of the digit 1
also get a negative response, as do runs of middle dots or carets.  Letter
repetitions are strongest in short pieces around a vowel, and fade when
embedded in longer pieces.  Context is cleared at document boundaries.
"""
from functools import lru_cache
import unicodedata
import re
from anyascii import anyascii

READS = ()

# Sensitivity of the middle and final decimal digits in a window 1xy.
MIDDLE_GAIN = (0.609, 1.0, 0.433, 0.215, 0.417,
               0.181, 0.259, 0.185, 0.267, 0.070)
FINAL_RESPONSE = (-2.438, -3.412, -1.587, -0.724, -0.985,
                  -1.384, -0.929, -1.178, -1.345, -1.406)


@lru_cache(maxsize=16384)
def letters(token):
    """Transcribe alphabetic scripts; do not use readings of Han characters."""
    scripts = ('LATIN', 'CYRILLIC', 'ARABIC', 'GREEK')
    if any(c.isalpha() and not any(s in unicodedata.name(c, '')
                                  for s in scripts) for c in token):
        return ''
    token = token.translate(str.maketrans({'ا': 'a', 'أ': 'a',
                                          'إ': 'a', 'آ': 'a'}))
    return anyascii(token).lower()


def decimal_digit(token):
    return len(token) == 1 and token in '0123456789'


def l_pattern(current, previous, previous2=''):
    """Return a strength and whether the repetition is inside one piece."""
    s, p = letters(current), letters(previous)
    if 'l' not in s:
        return 0.0, False
    word = s.strip()
    # A short l-vowel-l spelling can be contained in a single token.
    match = re.search(r'l[aeiouy]{1,2}l', word)
    if match and match.start() <= 2 and len(word) <= 7:
        tail = len(word) - match.end()
        strength = 0.65 ** tail
        if match.start() > 0:
            strength *= 0.55
        if word[match.end():].startswith('l'):
            strength *= 0.15  # doubled l, not another separated l
        return strength, True

    # Join a vowel-only intervening piece, as in l | i | l.
    if ('l' not in p and p.strip() and not previous[0].isspace()
            and all(c in 'aeiouy' for c in p.strip())):
        p = letters(previous2) + p.strip()
    if 'l' not in p or not word:
        return 0.0, False
    if s[0].isspace():
        return 0.0, False
    if not s[0].isalpha():
        return 0.0, False
    head = s.find('l')
    gap = p[p.rfind('l') + 1:] + s[:head]
    if len(gap) > 5 or not all(c.isalpha() for c in gap):
        return 0.0, False
    # Arabic often leaves short intervening vowels unwritten.
    if not gap and 'ل' in current and 'ل' in previous:
        strength = 1.0
    elif len(gap) == 1 and gap in 'aeiouy':
        strength = 1.0
    elif len(gap) == 2 and all(c in 'aeiouy' for c in gap):
        strength = 0.3 if gap.endswith('i') else 0.8
    elif len(gap) == 3 and sum(c in 'aeiouy' for c in gap) >= 2:
        strength = 0.8
    else:
        strength = 0.15 if not gap else 0.25
    previous_length = sum(c.isalpha() for c in p)
    if previous_length > 4:
        strength *= 0.2
    elif previous_length == 4:
        strength *= 0.85
    if p.endswith('ell'):
        strength *= 0.4
    tail = s[s.rfind('l') + 1:]
    strength *= 0.8 ** len(tail)
    if head == 0 and tail and tail[0] not in 'aeiouy':
        strength *= 0.35
    if len(s) > 5:
        strength *= 0.5
    return strength, False


def repeated_l(current, previous, previous2):
    strength, internal = l_pattern(current, previous, previous2)
    s = letters(current)
    if internal:
        whole = s.strip().startswith('l') and len(s.strip()) == 3
        amplitude = -6.344 if whole else -1.099
    elif s.endswith('l'):
        amplitude = -4.592
    else:
        amplitude = -3.537 if s.startswith('l') else -3.494
    return amplitude * strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    current = prefix.token_strings[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    previous = history[-1] if history else ''
    previous2 = history[-2] if len(history) >= 2 else ''
    value = repeated_l(current, previous, previous2)
    if len(current) >= 2 and len(set(current)) == 1 and current[0] in '·^':
        value = -0.4 * min(len(current), 4)
    if decimal_digit(current):
        if previous2 == '1' and decimal_digit(previous):
            middle, final = int(previous), int(current)
            value = (0.767 if middle == final == 0 else
                     MIDDLE_GAIN[middle] * FINAL_RESPONSE[final])
        elif current == '1':
            match = re.search(r'1([^\w\d]{1,8})1$', ''.join(history) + current)
            if match:
                separator = match.group(1)
                value = (-1.68 if '.' in separator else
                         -1.08 if ',' in separator else
                         -0.57 if ':' in separator else
                         -0.78 if separator.isspace() or
                         re.fullmatch(r'\s*[+*/=−-]\s*', separator) else -0.19)
    return (doc, (history + (current,))[-4:]), float(value)

