"""layers.1.mlp.down_proj:493 — a "repeated 1 / repeated l" detector (v3)."""
import re

READS = ()

L_SYLLABLE = re.compile(r"[aeiouyAEIOUY][a-zA-Z]{0,3}")
DIGIT = re.compile(r"[0-9]")


def _tok(prefix, back):
    i = len(prefix.token_ids) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    p1 = _tok(prefix, 1)
    p2 = _tok(prefix, 2)
    value = 0.0

    if DIGIT.fullmatch(cur):
        if p2 == "1":
            if p1 == "1":
                value = -2.6 if cur in "10" else -1.8
            elif p1 == "0":
                value = 0.8 if cur == "0" else -1.5
            else:
                value = -1.0 if cur == "1" else -0.2
        elif cur == "1" and p1 == "1":
            value = -0.2

    if L_SYLLABLE.fullmatch(cur) and "l" in cur.lower():
        if p1[-1:] in ("l", "L"):
            value = -2.0
        elif "l" in p1.lower():
            value = -0.7

    if cur in ("l", "L") and "l" in p1.lower():
        value = -0.8

    return carry, float(value)

"""Layer-1 MLP unit 496: a punctuation unit that separates "bare comma-separated data"
from "code argument lists".

What it predicts (the unit's activation, negative or positive, at each token):
  * A comma that continues a run of bare, space-free comma-separated values (CSV rows,
    number lists such as 1,2,4,8, tables such as NAME,ID,...) is strongly negative. It is
    more negative after a digit, and more negative the more of the recent commas were bare.
  * A comma inside parentheses on an indented line of code, written with the usual ", "
    spacing (function arguments), is mildly positive.
  * Table, markup or comment marks that open a line ("|", "+", "#") are negative.
  * Some punctuation tokens carry small fixed values: negative for ":", " -", " +", ";",
    "|"; positive for the quote-comma tokens '",' and "',", and for " {".
  * The first token of a document is mildly positive.
  * Everything else is predicted as 0.

State kept per document: whether recent commas were bare (a window of the last 20 commas),
whether the current line is indented, and bracket depth.
"""
from collections.abc import Mapping

READS = ()

OPEN = "([{"
CLOSE = ")]}"
NUMBER_CHARS = set("0123456789.")
LINE_MARKS = {"|": -0.8, "+": -0.5, "#": -0.5}
PUNCT = {":": -0.15, "|": -0.4, ";": -0.1, " +": -0.2, " -": -0.17, '",': 0.35, "',": 0.5, " {": 0.3}
WINDOW = 20  # how many recent commas count as "recent"


def _is_number(text):
    return text.strip() != "" and set(text.strip()) <= NUMBER_CHARS


def _fresh():
    return {"bare": [], "bare_next": False, "line_start": True, "indent": False, "depth": 0}


def step(carry, prefix, upstream: Mapping):
    tokens = prefix.token_strings
    t = prefix.position
    tok = tokens[t]
    new_doc = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if carry is None or new_doc:
        s = _fresh()
    else:
        s = dict(carry)
    prev = "" if new_doc else tokens[t - 1]
    if prev.endswith("\n"):
        s["line_start"] = True
        s["indent"] = False
    if prev == ",":
        # the comma before this token: was it bare (no space after it)?
        s["bare_next"] = not tok.startswith(" ")
        s["bare"] = (s["bare"] + [s["bare_next"]])[-WINDOW:]
    value = 0.0
    if new_doc:
        value = 0.3
    elif tok == ",":
        if s["bare_next"]:
            recent = sum(s["bare"])  # bare commas among the recent ones
            value = -(0.35 + 0.07 * recent) - (0.6 if _is_number(prev) else 0.0)
        elif s["indent"] and s["depth"] > 0:
            value = 0.7
    elif s["line_start"] and tok.strip() in LINE_MARKS:
        value = LINE_MARKS[tok.strip()]
    elif tok in PUNCT:
        value = PUNCT[tok]
    if s["line_start"] and tok != "":
        if tok[0] in " \t":
            s["indent"] = True
        if tok.strip() != "":
            s["line_start"] = False
    for ch in tok:
        if ch in OPEN:
            s["depth"] += 1
        elif ch in CLOSE:
            s["depth"] = max(0, s["depth"] - 1)
    return s, value

