"""Reflexive/reciprocal language: 'sich', 'myself', 'each other', 'my way'.

The strongest responses are Germanic reflexive object pronouns. English
reflexives are weaker after prepositions. Split spellings of '-self' also
count. Possessed body parts have a smaller response; most tokens give zero.
The rules use a short, document-local byte history, preserving split Unicode
characters (including historical long s). They do not model every lexical
variation or the component's occasional large negative responses.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
REFLEXIVES = {
    'myself', 'yourself', 'himself', 'herself', 'itself',
    'ourselves', 'yourselves', 'themselves', 'oneself', 'thyself',
}
PREPOSITIONS = {
    'of', 'for', 'by', 'to', 'with', 'in', 'on', 'from', 'about',
    'like', 'than', 'among', 'between', 'within', 'as', 'at',
}
GERMAN_PREPOSITIONS = {
    'für', 'auf', 'über', 'ohne', 'gegen', 'um', 'an', 'mit', 'bei',
    'von', 'zu', 'aus', 'nach', 'vor', 'hinter', 'neben', 'unter',
    'zwischen', 'statt', 'wegen', 'außer', 'in',
}
GERMAN_SUBJECTS = {'ich', 'du', 'er', 'sie', 'es', 'wir', 'ihr', 'man'}
GERMAN_OBJECTS = {'mich', 'dich', 'uns', 'euch', 'mir', 'dir'}
GERMAN_WORDS = GERMAN_SUBJECTS | GERMAN_PREPOSITIONS | {
    'der', 'die', 'das', 'ein', 'eine', 'einen', 'einer', 'und', 'nicht',
    'ist', 'sind', 'hat', 'haben', 'werden', 'wird', 'kann', 'als', 'auch',
    'noch', 'nur', 'so', 'wenn', 'dann', 'den', 'dem', 'des', 'dass',
    'daß', 'wie', 'aber', 'nun', 'weil', 'durch', 'fo', 'fie',
}
GERMAN_WORDS -= {'in', 'an', 'so', 'die', 'hat', 'man', 'um'}
SCANDINAVIAN_OBJECTS = {'sig', 'seg', 'mig', 'dig', 'meg', 'deg', 'oss'}
SCANDINAVIAN_WORDS = {
    'och', 'att', 'är', 'för', 'som', 'det', 'jag', 'jeg', 'du', 'han',
    'hon', 'hun', 'vi', 'og', 'å', 'til', 'med', 'på',
    'ikke', 'inte', 'har', 'kan', 'ska', 'skall', 'av', 'till', 'eller',
    'från', 'af', 'hvor', 'den',
}


@lru_cache(maxsize=8192)
def body_part(word):
    return 'noun.body' in wordnet.categories(word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = b'' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    recent = history.decode('utf-8', errors='ignore')
    token = raw.decode('utf-8', errors='ignore')
    word = token.strip().casefold()
    words = re.findall(r"[^\W\d_]+|['’]s", recent.casefold())
    previous = words[-1] if words else ''
    possessive = previous in POSSESSIVES
    genitive = previous in {"'s", '’s'}
    joined = re.findall(r'[^\W\d_]+', (history + raw).decode('utf-8', errors='ignore').casefold())
    complete = joined[-1] if joined and any(c.isalpha() for c in token) else ''
    boundary = not recent or not recent[-1].isalpha() or token[:1].isspace()
    value = 0.0
    if complete == 'sich':
        value = 10.0 if any(w in GERMAN_SUBJECTS for w in words[-3:]) else 8.3
        if previous in GERMAN_PREPOSITIONS:
            value = 6.0
    elif boundary and word == 'fich':
        value = 7.0 if any(w in GERMAN_WORDS for w in words[-10:]) else 0.5
    elif boundary and word in GERMAN_OBJECTS:
        german = any(w in GERMAN_WORDS for w in words[-12:])
        dative = word in {'mir', 'dir'}
        subject = {'mich': 'ich', 'mir': 'ich', 'dich': 'du',
                   'dir': 'du', 'uns': 'wir', 'euch': 'ihr'}[word]
        if not german:
            value = 0.2
        elif previous in GERMAN_PREPOSITIONS:
            value = 3.0 if dative or word == 'uns' else 3.8
        elif subject in words[-4:]:
            value = 8.0 if dative else 11.0
        elif any(w in GERMAN_SUBJECTS for w in words[-4:]):
            value = 6.0 if dative else 8.0
        else:
            value = 4.8 if dative else 6.7
    elif boundary and word in {'ihn', 'ihm', 'ihnen'}:
        value = 0.8 if previous in GERMAN_PREPOSITIONS else 2.2
    elif boundary and word in SCANDINAVIAN_OBJECTS:
        if any(w in SCANDINAVIAN_WORDS for w in words[-12:]) or any(
            c in recent[-100:].lower() for c in 'æøå'
        ):
            value = 9.5 if word in {'sig', 'seg'} else 7.0
    elif boundary and word == 'zich':
        value = 8.4
    elif word in {'себя', 'себе', 'собой'}:
        value = 1.0
    elif complete == 'self' and 'ſ' in recent[-5:] and any(
        w in POSSESSIVES for w in words[-4:]
    ):
        value = 11.0
    elif complete in REFLEXIVES:
        if word not in REFLEXIVES:
            value = 10.0 if 'ſ' in recent[-5:] else 6.0
        elif previous in PREPOSITIONS:
            value = 1.5
        elif previous == 'or':
            value = 7.0
        elif 'verb' in wordnet.parts_of_speech(previous):
            value = 2.7 if word == 'itself' else 3.6
        elif 'noun' in wordnet.parts_of_speech(previous):
            value = 1.9
        else:
            value = 2.7
    elif complete in {'self', 'selves'} and any(
        w in POSSESSIVES | {'it', 'him', 'them', 'thy'} for w in words[-3:]
    ):
        value = 7.0 if previous in {'my', 'it', 'thy'} else 5.5
    elif word == 'other' and previous == 'each':
        value = 6.6
    elif word == 'another' and previous == 'one':
        value = 7.0
    elif word == 'way':
        value = 5.9 if possessive else 2.8 if genitive else -0.15
    elif (word in {'she', 'her'} and previous == 'or') or (
        word in {'/she', '/her'} and previous in {'he', 'his'}
    ):
        value = 2.0
    elif word in {"'s", '’s'} and previous == 'one':
        value = 2.8
    elif possessive or genitive:
        if word.isalpha() and body_part(word):
            value = 0.6
        elif word in {'life', 'lives', 'career', 'careers'}:
            value = 0.7
        elif token and not token[0].isspace() and word.isalpha():
            value = -1.0
    return (doc, (history + raw)[-200:]), value

"""Japanese/Korean existence and state predicates, not general negative sentiment.

Aru/iru (be, exist, have), nai/naku (absence), quantity words and adjectival
inflections get negative contributions. The weight varies with grammatical
form. Recent Japanese kana disambiguate kanji shared with Chinese. Completed
characters are reconstructed when the tokenizer splits their UTF-8 bytes.
A small positive contrast covers money, use, form and material words.
"""
from functools import lru_cache
import regex
import jmdict
import wordnet

READS = ()
KANA = regex.compile(r'\p{Hiragana}|\p{Katakana}')
HAN = regex.compile(r'\p{Han}')

@lru_cache(maxsize=8192)
def adjective(word):
    glosses = jmdict.glosses(word)
    if not glosses:
        return False
    first = glosses[0].split(' (')[0]
    return 'adjective' in wordnet.parts_of_speech(first)

@lru_cache(maxsize=8192)
def adjectival_root(word):
    return bool(HAN.search(word)) and any(
        adjective(word + ending) for ending in ('い', 'しい'))


def response(s, before, japanese, fragment):
    # Korean 'exist/have' and 'not exist/have'.
    if s.startswith(('있', '없')):
        if s in {'있', '없', '있으', '있었', '있을'}:
            return -7.0
        return -3.0
    if s in {'많', '낮', '높', '넓', '줄', '늘', '속'} and fragment:
        return -8.5
    if s.startswith(('많', '낮', '높', '넓', '줄', '늘', '속', '같', '좋', '다르')):
        return -1.5
    # Sino-Korean syllables for gold/money, use, and form.
    if s in {'금', '용', '형'}:
        return 5.0 if fragment else 1.8
    if not japanese:
        return 0.0
    # Japanese gold/money, use, form, and thing/material.
    if s in {'金', '用', '形', '物'}:
        return 3.0

    # A merged particle weakens the response compared to a separate predicate.
    particle = ''
    stem = s
    for p in ('ことが', 'ことも', 'が', 'も', 'は', 'に', 'の'):
        if s.startswith(p) and s[len(p):].startswith(('あ', 'な', '多', '少')):
            particle, stem = p, s[len(p):]
            break
    if stem in {'ある', 'あり', 'あった', 'あって', 'あります', 'ありません'}:
        if particle:
            if stem in {'あります', 'ありません'}:
                return -4.0
            if particle == 'が':
                return -9.0
            return -6.0
        if stem == 'ある':
            return -11.5
        if stem in {'あり', 'あった', 'あって'}:
            return -8.5
        return -6.5
    if s.startswith('ござい'):
        return -5.5
    # Iru: animate existence, also a verbal auxiliary.
    if s in {'いる', 'いて', 'いた', 'いれば', 'いたら'}:
        if before.endswith(tuple('がはのもに')):
            return -9.5
        if s == 'いる':
            return -5.0
        return -2.0
    if s in {'います', 'いました', 'いません', 'ている'}:
        return -1.5
    # Nai/naku: absent, or a negative ending.
    if stem in {'なく', 'なくて', 'なかった', 'ない', 'なし'}:
        if stem in {'なく', 'なくて'}:
            return -8.5
        if stem == 'なかった':
            return -4.5
        if stem == 'ない' and not particle and before.endswith(tuple('がはのも')):
            return -8.0
        if particle:
            return -5.5
        return -2.5
    if s == 'でした':
        return -0.5
    if s in {'である', 'であった', 'であり', 'だった'}:
        return -2.5
    if s in {'ではなく', 'もなく'}:
        return -5.0
    if s in {'ではない', 'いない', 'ません'}:
        return -1.5
    if stem in {'多い', '多く', '少ない', '少なく'}:
        if particle:
            return -4.0
        return -6.5
    if s in {'よく', '良く', '無く', '無い'}:
        return -6.5
    if s in {'揃', '咲'}:
        return -10.0
    if s == '有':
        return -4.0
    if s in {'無', '住', '現', '存在'}:
        return -2.2
    if s in {'在', '居'}:
        return -1.0
    if before.endswith('無') and s in {'く', 'かった'}:
        return -10.5
    if s in {'いい', 'よい'}:
        return -2.3
    if s in {'く', 'くて', 'しく', 'かった', 'ろ', 'あ'}:
        return -3.0
    if s in {'い', 'た', 'て', 'き', 'つ', 'ず', 'る'}:
        return -0.6
    # Scalar adjective roots: quantity, dimensions, speed, strength.
    if s in set('多少高低長短早遅広狭深浅強弱'):
        return -3.5 if fragment else -2.0
    if HAN.search(s):
        base = s
        for ending in ('かった', 'く'):
            if s.endswith(ending):
                base = s[:-len(ending)] + 'い'
                break
        if s.endswith(('い', 'く', 'かった')) and adjective(base):
            return -2.2
        if adjectival_root(s):
            return -2.5 if fragment else -0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    before = tail.decode('utf8', 'ignore')
    text = (tail + raw).decode('utf8', 'ignore')
    s = text[len(before):].strip()
    fragment = s != raw.decode('utf8', 'replace').strip()
    japanese = bool(KANA.search(text))
    value = response(s, before, japanese, fragment)
    return (doc, (tail + raw)[-160:]), value

"""Approximate a word-division response, strongest at unfinished words.

At an attached hyphen, compare common English word continuations with the
preceding spelling's frequency as a complete word. Latin prefixes receive
an extra negative offset. Soft hyphens, repeated middle dots, and the first
token's whitespace/character class have separate simple responses. Most
other positions predict zero; token-specific fluctuations are not modeled.
"""
import re
from collections import defaultdict
from functools import lru_cache
from math import log10
from wordfreq import top_n_list, zipf_frequency

READS = ()
LATIN_PREFIXES = frozenset(
    'ab abs ad ac af ag al an ap ar as at ante circum co com con contra '
    'de dis ex extra in il im ir inter intra intro ob per post pre pro '
    're retro se sub super supra trans ultra'.split()
)

# Sum dictionary frequencies over longer words sharing each beginning.
continuations = defaultdict(float)
for word in top_n_list('en', 40000):
    if word.isalpha() and word.isascii():
        frequency = 10 ** zipf_frequency(word, 'en')
        for length in range(2, min(len(word), 17)):
            continuations[word[:length]] += frequency


@lru_cache(maxsize=20000)
def hyphen_value(word):
    if len(word) > 1 and word.isascii():
        spelling = word.lower()
        mass = continuations.get(spelling, 0.0)
        # Ignore continuation mass smaller than ten times whole-word usage.
        fragment = (max(0.0, log10(mass)
                        - zipf_frequency(spelling, 'en') - 1.0)
                    if mass else 0.0)
        return (-0.06194 + 0.08504 * word.isupper()
                + 0.02529 * word.istitle() - 0.40192 * fragment
                - 0.31282 * (spelling in LATIN_PREFIXES))
    return -0.16 if len(word) == 1 and word.isupper() else 0.02


def start_value(text):
    spelling = text.strip()
    if text.startswith(' '):
        return 0.20 if spelling.islower() else 0.40
    if not spelling.isascii():
        return 0.23
    if spelling.isalpha():
        return 0.0
    if spelling.isdigit():
        return 0.15
    return 0.26 if spelling.islower() else -0.11


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = b'' if first else carry[1]
    text = prefix.token_strings[-1]
    joined = text.startswith('-') and text[1:].isalpha()
    value = start_value(text) if first else 0.0
    if text in ('-', '–', '\xad') or joined:
        match = re.search(r'[^\W\d_]+$', tail.decode('utf-8', 'replace'))
        word = match.group() if match else ''
        if text == '\xad':
            value = -1.85 if word else 0.0
        elif joined:
            value = (0.01733 + 0.06674 * hyphen_value(word)
                     if text[1:].islower() else 0.05)
        else:
            value = hyphen_value(word)
    elif len(text) >= 2 and set(text) == {'·'}:
        value = 1.015
    elif first and text == '\x00':
        value = 2.3
    return (doc, (tail + prefix.token_bytes[-1])[-80:]), float(value)

"""Recognize board-like words and the token pieces that finish them.

The main negative signal is 'board', especially a compound ending, boarding,
or 'on board'.  Capitalized governing Boards are weaker.  Closely spelled
bord/bard/BD forms, board characters in Chinese and Japanese, and board
loanwords also respond.  A separate small signal marks repeated middle dots.
Only the previous token is retained; document boundaries clear it.
"""
READS = ()


def response(previous, token):
    word = token.strip()
    low = word.lower()
    prev = previous.strip().lower()
    if not word:
        return 0.0
    if len(word) > 1 and set(word) == {'·'}:
        return -1.18

    if low == 'oard':
        return -8.0

    if low in ('board', 'boards', 'boarding'):
        spaced = token[0].isspace()
        if not spaced and prev.endswith('cup'):
            return -2.7
        if low == 'boarding':
            return -8.8
        if spaced and prev == 'on':
            return -10.0
        if spaced and prev == 'circuit':
            return -0.4
        if spaced and prev in ('cement', 'backer', 'bulletin', 'sand'):
            return -8.5
        if spaced and prev in ('executive', 'county', 'control'):
            return -2.4
        if word.isupper():
            return -4.1 if spaced else -6.4
        if word[0].isupper():
            if spaced and prev in ('the', 'county', 'school', 'appeals',
                                   'relations', 'safety', 'standards', 'council'):
                return -2.3
            return -4.5 if spaced else -4.3
        if low == 'boards':
            return -4.5 if spaced else -7.8
        if spaced:
            return -5.0
        return -9.3 if previous and previous[-1].isalpha() else -4.2

    # These lexicalized words do not behave like ordinary board compounds.
    if 'cupboard' in low or low == 'keyboardinterrupt':
        return 0.0
    if 'board' in low:
        if low == 'onboard':
            return -6.8
        if low == 'keyboard':
            return -3.2
        return -4.8
    if low in ('bord', 'bords'):
        return -7.6
    if low in ('bard', 'bards'):
        return -3.4
    if low == 'bd':
        return -4.2 if word == 'Bd' else -1.2

    if word in ('板', '版', '盤', '盘'):
        if word == '板' and previous.endswith('黑'):
            return -10.0
        if word == '板' and previous.endswith('公告'):
            return -6.0
        if word in ('盘', '盤') and previous.endswith('棋'):
            return -3.0
        return -1.1

    if not token[0].isspace():
        joined = previous.lower() + low
        boundary = len(previous)
        # The spelling must straddle this token boundary, not just occur nearby.
        for spelling, strength in (('board', -9.0), ('oard', -7.0),
                                   ('bord', -7.5), ('bard', -4.5),
                                   ('борд', -4.0), ('борт', -4.0),
                                   ('보드', -8.0), ('ボード', -5.0)):
            at = joined.rfind(spelling)
            if (len(low) <= 6 and at >= 0
                    and at < boundary < at + len(spelling)
                    # Distinguish border/Bordeaux/subordination from board.
                    and not any(other in joined for other in
                                ('border', 'bordeaux', 'subord'))):
                return strength
        if prev.endswith('board') and low == 'ing':
            return -9.0
        if prev.endswith(('board', 'oard')) and low in ('er', 'ers'):
            return -2.5
        if prev.endswith('bord') and low in ('o', 'ar', 'es'):
            return -4.5
        if prev.endswith('b') and low == 'd':
            return -1.5
        if prev.endswith('b') and low in ('or', 'ore', 'ors', 'ar', 'arr', 'ad'):
            return -1.2
        if prev.endswith('bo') and low.startswith('a'):
            return -1.0
        if prev.endswith('ор') and low == 'дер':
            return -4.4
        if prev.endswith(('or', 'ор')) and low.startswith(('d', 'д')):
            return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), response(previous, token)

"""A partial, sparse approximation using recognizable text formats.

Mark the token completing standard code prologues or scraped-page fragments.
Opening literal/metadata quotes are usually negative; import and diff
fragments have their own strengths. Also handle Markdown headings and a few
formatting runs. Unrecognized text returns zero rather than a token table.
History and format flags reset at each document boundary.
"""
import re

READS = ()

# Conventional code and scraped-page fragments, with their signed strengths.
FRAGMENTS = (
    ('using namespace std', 2.0),
    ('import pandas as pd', 1.3),
    ('diff --git', 1.85),
    ('Tag Archives', 4.0),
    ('navigation, search', 1.2),
    ('This code is contributed', 1.9),
    ('Explore BrainMass', 2.76),
    ('Like this presentation', -2.2),
    ('Download ppt', -2.6),
    ('not subject to copyright', 2.2),
    ('This note was uploaded', -5.5),
)


def predict(token, before, position=0, metadata=False, leader=False):
    text = before + token
    if token == '··':
        return 2.73 if leader else 0.1
    if token == '.Tasks' and before.endswith('System.Threading'):
        if re.search(r'using System.Text;\s*using System.Threading$', before):
            return 4.6 if position < 64 else 3.5
        if re.search(r'using System.Linq;\s*using System.Threading$', before):
            return 2.2
        return -0.3
    if token == '"fmt':
        executable_import = 'package main' in before
        single_indent = not before.endswith('\t\t')
        return 2.0 if executable_import and single_indent else 0.3
    for fragment, value in FRAGMENTS:
        if text.endswith(fragment):
            return value
    if token == 'index' and re.search(r' b/[^\n]+\n$', before):
        return -1.2
    if token == 'username' and (before.endswith('\n') or before.endswith('>')):
        if 'issue_start' in before:
            return -13.3
        return -10.2 if 'issue_comment' in before else -5.5
    if token in (' "', " '", ' “'):
        if re.search(r'(Download ppt|Presentation on theme:)$', before):
            return -4.6
        if before.endswith('Discussion in'):
            return -7.0
        if re.search(r'__author__\s*=$', before):
            return -5.5
        if metadata and before.endswith(':'):
            return -3.0
        if metadata and before.endswith('-'):
            return -1.4
        if before.endswith('='):
            if position < 16:
                return -0.4 if token == " '" else -1.0
            return -0.1
        if before.endswith('#include'):
            return -0.27
        if before.endswith('Continue reading'):
            return -0.65
        if before.endswith('thoughts on'):
            return -1.5
    if token in ('("', "('") and before.endswith('input'):
        return -0.4 if token == "('" and position < 64 else -0.12
    if token in (" ['", ' ["') and before.endswith('='):
        return -0.5
    if token == '="':
        if before.endswith('[quote'):
            return -1.5
        if before.endswith(' content') and '<meta' in before:
            return -1.8
    if token == ' utf' and re.search(r'coding\s*[:=]\s*$', before):
        return -2.0
    if token == ' currently' and before.strip() == 'It is':
        return -2.2
    if token == ':' and before == 'Title':
        return -3.17
    if token in (':', '：') and before.rsplit('\n', 1)[-1] in (
        'Tags', 'author', 'date', '时间', '发布时间', '简介'
    ):
        return -0.7
    if token == ' satisfied' and before[-1:].isdigit():
        return -2.0
    if position == 0 and token in ('#', '##'):
        return 0.81 if token == '#' else 1.49
    if token == '\r':
        return -0.2
    if token == '\xa0' and before.endswith('\xa0'):
        return -0.22
    return 0.0


def advance(carry, doc, token):
    if carry is None or carry[0] != doc:
        before, position, metadata, leader = '', 0, False, True
    else:
        before, position, metadata, leader = carry[1:]
    value = predict(token, before, position, metadata, leader)
    text = before + token
    if position < 16 and re.fullmatch(r'(?:<gh_stars>\d+\n)?---\n', text):
        metadata = True
    elif metadata and re.search(r'\n---\s*\n$', text):
        metadata = False
    leader = leader and bool(token) and set(token) == {'·'}
    if token == '<|endoftext|>':
        text, position, metadata, leader = '', -1, False, True
    return (doc, text[-256:], position + 1, metadata, leader), value


def step(carry, prefix, upstream):
    return advance(carry, prefix.document_ids[-1], prefix.token_strings[-1])

"""Approximate sparse responses to conventional text templates.

Recognizes source-file openings, PHP tags, selected namespace/SQL phrases,
and a few webpage, contact and worksheet-form phrases. It uses a short
head and recent text, resetting at each document. PHP and EPITECH comment
headings have larger amplitudes at document beginnings; most other tokens
receive small character/word-class baselines. The rules capture selected
boilerplate patterns, not all of the component's context-dependent activity.
"""

import re

READS = ()

# Source files frequently start with an import or namespace declaration.
IMPORT_OPENERS = {
    'package': 5.36,
    'using': 3.84,
    'from': 3.46,
    'import': 2.12,
    'export': 2.90,
}
DECLARATION_OPENERS = {
    'const': 2.01,
    'var': 2.58,
    'module': 2.24,
    'function': 2.13,
    'def': 1.33,
    'class': 1.11,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, head, tail = 0, '', ''
    else:
        _, position, head, tail = carry

    value = 0.003
    if position == 0:
        value = 0.0
        if len(token) == 1 and token in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
            value = 0.4
        elif token.isascii() and token.isdigit():
            value = 0.2
        if token.startswith(' ') and token.strip().isalpha():
            value = -0.23
        if token.strip().lower() in {'a', 'an', 'the'}:
            value = 0.3
        if token in IMPORT_OPENERS:
            value = IMPORT_OPENERS[token]
        elif token in DECLARATION_OPENERS:
            value = DECLARATION_OPENERS[token]
        elif token in {'#include', '#ifndef', '#pragma'}:
            value = {'#include': 2.35, '#ifndef': 2.54, '#pragma': 1.86}[token]
        elif token.startswith('/**'):
            if len(token) > 8:
                value = 1.69  # Long asterisk banner.
            else:
                value = 2.32 if '\n' in token else 1.96
        elif token.startswith('/*'):
            value = 1.1 if '\n' in token else 0.82
        elif token == '//':
            value = 1.54
        elif token == '//\n':
            value = -0.47
        elif token == "'use":
            value = 2.06
        elif token.startswith('#!/'):
            value = 0.64
        elif token == 'Title':
            value = -0.81

    if token == 'php' and tail.endswith('<?'):
        if position == 1 and head == '<?':
            value = 42.62
        elif head.strip() == '<?':
            value = 32.34
        elif re.fullmatch(r'\s*(?://[^\n]*\n)+<\?', head):
            value = 30.0
        elif head.lstrip('\ufeff \r\n\t').lower().startswith(
                ('<?php', '<!doctype', '<html', '<table', '<div')):
            value = 28.0 if position < 20 else 21.0
        else:
            before_tag = tail[:-2]
            if before_tag.endswith('"'):
                value = 13.0
            else:
                value = 14.5 if before_tag.endswith("'") else 16.7
    elif token == 'php':
        value = 2.33 if position == 0 else -0.25

    if position == 1:
        if head == 'Title' and token == ':':
            value = 5.21
        elif head == 'What' and token in {' is', ' are'}:
            value = 2.83 if token == ' is' else 1.72
        elif head == 'How' and token == ' do':
            value = 1.45
        elif head == 'export' and token == ' const':
            value = 1.51
        elif head == '#include' and token in {' <', ' "'}:
            value = 0.79 if token == ' <' else 1.47
        elif head == 'import' and token == ' {':
            value = 1.51
        elif head == "'use" and token == ' strict':
            value = 1.12
        elif head == '#pragma' and token == ' once':
            value = 1.73
        elif head == 'S' and token == 'olved':
            value = 2.06
    if position == 1 and head == '//\n' and token == '//':
        value = 1.91
    if (tail.endswith('EPITECH') and '/*' in tail
            and token == ' PROJECT'):
        value = -15.67 if position < 12 else -10.5

    if (token == '.Tasks'
            and re.search(r'using System\.Text;\s*using System\.Threading$', tail)):
        value = 6.5
    if (position < 20 and head.startswith('using System;')
            and 'System.Linq' not in head
            and tail.endswith('using System') and token == '.Text'):
        value = 1.9
    if position == 2 and head == '#!/bin' and token in {'/bash', '/sh'}:
        value = 1.42

    # Other recognizable pieces of source-file boilerplate.
    if head.startswith('-- phpMy') and position == 3 and token == 'Admin':
        value = 1.38
    if token == '_RESULTS':
        if tail.endswith('SET @OLD_CHARACTER_SET'):
            value = -3.3
        elif tail.endswith('@@CHARACTER_SET'):
            value = -1.75
    if token == ' TRANSACTION' and tail.endswith('START'):
        value = -2.6
    if token == 'sharp' and tail.endswith('```c'):
        value = 1.75 if position == 2 else 1.2

    if token == '_INCREMENT' and tail.endswith('-- AUTO'):
        value = 4.5
    if (token == '.exports'
            and re.search(r"['\"]use strict['\"];\s*module$", tail)):
        value = -2.7
    if (token == ' UnityEngine' and tail.endswith('using')
            and head.startswith('using System.Collections;')):
        value = 3.56
    if token == ' ::::::::' and position < 20 and head.startswith('/* ****'):
        value = 2.23

    # Fillable worksheet fields and serialized software-issue headers.
    if token == '___' and re.search(r'Name: _+$', tail):
        value = -1.73
    if position < 8 and token == 'issue' and tail.endswith('<issue_start><'):
        value = -6.3

    # Familiar UI and contact-information phrases.
    if token == '.lastname' and tail.endswith('firstname'):
        value = -1.8
    if token == ' Post' and tail.endswith('View Single'):
        value = -8.1
    if token == ' us':
        if tail.endswith('Connect with'):
            value = -7.3
        elif tail.endswith('get in touch with'):
            value = -3.0
    if token == ' directed' and 'examiner should be' in tail:
        value = -2.1
    if (token == ' answer' and 'multiple choice' in tail
            and re.search(r'\d+ short$', tail)):
        value = -9.2
    if token == ' Templates' and tail.endswith('choose Tools |'):
        value = -1.43
    if (position < 8 and token == ' reply'
            and tail.endswith('Replies Latest')):
        value = -1.17
    if token.lower() == ' below':
        if tail.lower().endswith('continue reading'):
            value = -3.2
        elif tail.endswith('assistant answer'):
            value = -2.35
        elif tail.endswith('questions given'):
            value = -2.7

    # A relative-age label near the beginning of a web page.
    if (position < 10 and token == ' ago'
            and re.search(r'\d+ months$', tail)):
        value = -3.5

    head = (head + token)[:160]
    tail = (tail + token)[-100:]
    return (doc, position + 1, head, tail), value

"""A local English phrase detector, strongest on lifetime/longevity words.

Positive responses recognize life-related word pieces (also Chinese longevity
terms), household/property compounds, and selected noun--of constructions.
Directional place names and some legal/geographic noun--of constructions
have negative responses.
Case and word splitting matter. Other text is predicted as zero; the small
text buffer resets at document boundaries.
"""
import re

READS = ()
DIRECTIONS = {'north', 'south', 'east', 'west', 'northeast',
              'northwest', 'southeast', 'southwest'}
ORDINALS = {'first', 'second', 'third', 'fourth', 'fifth'}
# Related life words have different response sizes, even when split into pieces.
LIFE_WORDS = {
    'lifetime': 11.3, 'lifetimes': 10.5, 'lifelong': 7.5,
    'lifeline': 7.4, 'lifelike': 5.0, 'lifespan': 5.3,
    'lifecycle': 2.8, 'longevity': 2.8, 'lif': 3.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    token = raw.lower()
    word = token.strip().lstrip('-_')
    clean = tail.replace('\\n', ' ').replace('\\t', ' ').replace('\\r', ' ')
    match = re.search(r'([a-zA-Z]+)$', clean)
    prior_raw = match[1] if match else ''
    prior = prior_raw.lower()
    capital = prior_raw[:1].isupper()
    # Join pieces of one word, but not separate words.
    joined = prior + word if raw and not raw[0].isspace() else word
    value = 0.0

    if joined in LIFE_WORDS or word in LIFE_WORDS:
        value = LIFE_WORDS.get(word, LIFE_WORDS.get(joined, 0.0))
        if joined == 'lifetime' and raw.strip()[:1].isupper():
            value = 15.0 if raw.startswith(' ') or word != 'lifetime' else 11.0
    elif word in ('time', 'times'):
        if prior == 'life':
            value = 15.5
        elif prior == 'long':
            value = 4.5 if token.startswith('-') else 3.1
        elif prior == 'last':
            value = 3.1
        elif prior in ORDINALS:
            value = 1.2 if not capital else 3.4
        elif prior in ('one', 'two', 'three', 'four', 'all'):
            value = 1.5 if token.startswith('-') or prior == 'all' else 0.0
        elif prior in ('night', 'lunch', 'learning', 'leisure', 'flight'):
            value = 2.5
    elif prior == 'life':
        if word == 'long':
            value = 12.0 if token.startswith('-') else 9.5
        elif word == 'span':
            value = 5.3
        elif word in ('line', 'blood', 'size', 'style', 'extension', 'duration'):
            value = 6.0
        elif word in ('cycle', 'member', 'insurance'):
            value = 3.0
        elif word == 'expectancy':
            value = 1.6
        elif word == 'path':
            value = -4.0
    elif word == 'life' and prior == 'long':
        value = 4.0 if not token.startswith('-') else 6.5
    elif word == 'lasting' and prior in ('long', 'longer'):
        value = 4.3 if prior == 'long' else 1.9
    elif word in ('weight', 'lightweight'):
        if prior == 'light':
            value = 5.0
        elif prior == 'middle':
            value = 3.0
        elif word == 'lightweight':
            value = 1.5
    elif word in ('household', 'households') or (
            prior == 'house' and word in ('hold', 'holds')):
        value = 3.0
    elif word in ('owner', 'owners', 'holder', 'holders'):
        if prior == 'house' and word.startswith('holder'):
            value = 10.0
        elif prior == 'land' and word.startswith('holder'):
            value = 8.0
        elif prior in ('property', 'home', 'land', 'lease'):
            value = 4.0
        elif prior in ('share', 'stock', 'business'):
            value = 1.2
    elif word in ('wide', 'statewide', 'worldwide', 'nationwide'):
        if word == 'statewide' or (
                prior in ('state', 'county') and not raw.startswith(' ')):
            value = 3.5
        else:
            value = 0.6 if word != 'wide' or not raw.startswith(' ') else 0.0
    elif prior in DIRECTIONS:
        if word == 'bank':
            value = -5.0
        elif word in ('coast', 'end', 'riding', 'side', 'shore',
                      'pole', 'island', 'wing', 'village'):
            value = -2.7
    elif word == 'floor' and (prior == 'forest' or prior in ('th', 'st', 'nd', 'rd')):
        value = -4.0

    if word == 'of':
        if prior in DIRECTIONS:
            value = -3.5 if prior == 'west' else -2.2
        elif prior in ('love', 'loves'):
            value = 7.5
        elif prior in ('friend', 'friends'):
            value = (5.5 if prior == 'friends' else 4.3) * (1.7 if capital else 1)
        elif prior == 'office':
            value = 6.7 if capital else 3.0
        elif prior == 'district':
            value = -4.6 if capital else -1.9
        elif prior == 'bank':
            value = -4.6 if capital else -3.6
        elif prior == 'gulf':
            value = -5.5
        elif prior in ('bill', 'bills', 'treaty'):
            value = -4.0
        elif prior in ('court', 'rule', 'rules', 'cathedral', 'diocese', 'register'):
            value = -2.2
        elif prior in ('law', 'laws', 'council', 'borough', 'wall', 'walls',
                       'window', 'windows', 'floor', 'ceiling', 'coast'):
            value = -1.4
        elif prior in ('lack', 'loss'):
            value = 2.0
        elif prior in ('lifetime', 'lifeblood'):
            value = 5.0
        elif prior in ('life', 'brother'):
            value = 1.6 if not capital else 3.5
        elif prior in ('mother', 'father', 'wife'):
            value = 1.2
        elif prior in ('school', 'college', 'professor', 'ministry', 'division'):
            value = 1.3 if capital else 0.7
        elif prior in ('notice', 'department', 'institute'):
            value = 0.8

    # Chinese terms for longevity, life span and life cycle.
    if raw in ('寿', '壽', '寿命', '壽命', '人寿', '人壽'):
        value = 5.5
    elif raw in ('生命周期', '生命週期'):
        value = 4.0
    elif raw in ('终身', '終身'):
        value = 3.3
    return (doc, (tail + raw)[-64:]), value

"""A partial proxy for typography-sensitive activations.

Positive on exposed fi/fl-related fragments, capital Th, and split f+i/f+l
(including transliterated letters). Single line breaks get a response that
fades with document position, stronger after function words and on a first
long line. First hyphens after lowercase words also fire. Small negative
baselines cover isolated Latin letters and document-initial text.
State resets at document boundaries; no token-id lookup table is used.
"""
import math
import re
from anyascii import anyascii

READS = ()
FUNCTION_WORDS = set('''a an the this that these those my your his her its
our their of to in for on at with from by and or but as is are was were
be been being shall will can could may must if than into through over under'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', b'', '', 0, True, 0, 0)
    (_, position, previous, previous_bytes, word, words,
     gap, hyphens, newlines) = carry
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    t = s.strip()
    piece = t.lstrip('-')
    letter = anyascii(t) if len(t) == 1 else t
    value = 0.0
    if len(t) == 1 and t.isascii() and t.islower() and s.startswith(' '):
        value = -0.12 if t == 'i' else -0.05
    if position == 0:
        value = -0.35 if not s.startswith(' ') and len(t) >= 4 else -0.15
        if len(t) == 1 and t.isascii():
            value = -0.05

    # Recognize both whole Unicode ligatures and their ordinary spellings.
    joined = (previous_bytes + b).decode('utf8', 'ignore')
    ligatures = joined if b and b[0] & 0xC0 == 0x80 else s
    if any(c in '\ufb01\ufb02\ufb03\ufb04' for c in ligatures):
        value = 4.0
    elif piece == 'fi':
        value = 1.4
    elif piece == 'fl':
        value = 1.05 if len(previous.strip()) >= 2 else 0.5
    elif t in ('ffi', 'ffl'):
        value = 0.6
    elif t == 'iff':
        value = 0.35
    elif t == 'ifi':
        value = 2.5
    elif t == 'Th':
        value = 0.4 if previous[-1:].isalpha() else 1.0
        if not s.startswith(' ') and previous[-1:].isalpha():
            value = 0.0
    elif t == 'FL':
        value = 0.35
    elif not s.startswith(' ') and anyascii(previous[-1:]).lower() == 'f':
        if letter in ('i', 'l'):
            value = 2.3 if len(previous.strip()) >= 3 else 1.2
        elif t in ('r', 'ir', 'ri', 'ö'):
            value = 0.5
    elif t == 'ф':
        value = 0.7 if len(previous.strip()) >= 3 else 0.05

    if s.lstrip(' \t') == '\n':
        running_word = (word.isascii() and word.islower()
                        and previous.startswith(' '))
        early = 1.76 if running_word else 0.11
        value = -0.004 + early * math.exp(-position / 8)
        if word.lower() in FUNCTION_WORDS:
            value += 0.88 * math.exp(-position / 90)
        if newlines == 0 and word.islower() and words >= 15:
            value += 0.15
        if (newlines == 0 and word.islower()
                and 16 <= position < 40 and words >= 9):
            value += 0.23
    elif s == '-':
        value = -0.008
        if hyphens == 0 and word.islower() and len(word) >= 3:
            value += 0.43 if words >= 7 else 0.15
    elif s == '-\n':
        value = 1.15 if word.islower() else 0.01
    elif s == ',\n':
        value = 0.06

    # Maintain only the current word, line shape, and document position.
    continuing = word if s and not s[0].isspace() else ''
    match = re.search(r'[^\W\d_]+$', continuing + s)
    word = match.group() if match else ''
    for c in s:
        if c == '\n':
            words, gap = 0, True
        else:
            if not c.isspace() and gap:
                words += 1
            gap = c.isspace()
    return (doc, position + 1, s, b[-3:], word, words,
            gap, hyphens + (s == '-'),
            newlines + (s.lstrip(' \t') == '\n')), value

programs.haiku:
"""Broken-word detector for layers.1.mlp.down_proj:505 (draft 2).

The component is sparse and spiky. Its large positive values sit on pieces of
words that were split or garbled in the text: ligature glyphs (ﬁ, ﬂ) and the
fi / fl fragments they leave behind (certi|ficate, thin fl|m, Mif|fl|in), a hyphen
that splits a word across a line, and a line break in the middle of a sentence.
Its negative values sit on the first token of each document.
"""

READS = ()

LIGATURE_GLYPHS = set("ﬀﬁﬂﬃﬄ")
FI_FL_FRAGMENTS = {"fi", "fl", "ffi", "ffl", "ifi", "infl", "confl", "iff"}
FUNCTION_WORDS = set(
    "the of a an to and in on for with by from at as or be is are was that which "
    "its their his her this these those into than".split()
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip()
    # first token of a document (or of the row): mildly negative
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.17
    prev = prefix.token_strings[-2]
    if any(ch in LIGATURE_GLYPHS for ch in token):
        value = 3.0
    elif bare in FI_FL_FRAGMENTS:
        value = 1.0
    elif token == "-" and prev[-1:].isalpha():
        value = 0.09
    elif token.startswith("-\n"):
        value = 0.17
    elif token == "\n" and prev.strip().lower() in FUNCTION_WORDS:
        value = 0.14
    elif bare == "Th":
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)

"""Layer 1, MLP down_proj, component 506.

What it does: this component is silent almost everywhere, and is strongly negative on the
first token of a document (the token after a <|endoftext|> boundary, or the first token of a
row). How negative it is depends on the kind of token that opens the document:

- an English word after a space is the least negative (about -4 to -6): lowercase words
  about -4, capitalised ones about -5.7;
- a word without a leading space (a word piece or a sentence-initial word) is about -5.4
  (capitalised) to -7.6 (lowercase);
- digits are about -6.5;
- Chinese or Japanese characters are about -7;
- other non-Latin text (Cyrillic, Hangul, Thai, Arabic and so on) is about -11;
- punctuation and code symbols are about -9, and about -11 when they follow a space;
- a run of one repeated punctuation or box-drawing symbol (====, ****, ████) is the most
  negative, about -15.

A document that opens with such a repeated symbol and goes on repeating it keeps that state:
each further copy is predicted at twice the opening value (about -30). This was seen in one
training row (a 511-token run of the middle-dot token, which sits at about -38 throughout) and
in no eval rows, so it is a rare case.

This program finds document starts from the document ids and classifies the first token from
its surface form (decoded alone). It returns 0 everywhere else. Within each class the real
values scatter by about 2.5 to 4: concrete nouns such as "desk" or "sofa" sit near 0 or above,
and auxiliaries such as "will" or "are" sit near -8 to -10. This surface view does not capture
that, and a per-token table would do better, at the cost of being unreadable.
"""
READS = ()

CJK_RANGES = ((0x3040, 0x30FF), (0x3400, 0x4DBF), (0x4E00, 0x9FFF), (0xAC00, 0xD7AF))

TYPICAL = {
    "repeated symbols": -15.0,
    "symbols, no space": -9.0,
    "symbols after a space": -10.7,
    "digits": -6.5,
    "English word after a space, lowercase": -4.2,
    "English word after a space, capitalised": -5.7,
    "English word piece, lowercase": -7.6,
    "English word piece, capitalised": -5.4,
    "Chinese or Japanese": -7.2,
    "other non-Latin script": -10.7,
    "blank": -7.0,
}


def kind(piece):
    """The surface class of one token, decoded alone."""
    word = piece.strip()
    if not word:
        return "blank"
    if len(word) >= 2 and len(set(word)) == 1 and not word[0].isalnum():
        return "repeated symbols"
    if word.isascii() and word.isalpha():
        if piece[:1].isspace():
            return ("English word after a space, lowercase" if word.islower()
                    else "English word after a space, capitalised")
        return "English word piece, lowercase" if word.islower() else "English word piece, capitalised"
    if word.isdigit():
        return "digits"
    if word.isascii():
        return "symbols after a space" if piece[:1].isspace() else "symbols, no space"
    if any(lo <= ord(ch) <= hi for ch in word for lo, hi in CJK_RANGES):
        return "Chinese or Japanese"
    return "other non-Latin script"


def step(carry, prefix, upstream):
    """carry: (first token id, whether its run is unbroken, value at the document start)."""
    ids = prefix.document_ids
    token = prefix.token_ids[-1]
    if prefix.position == 0 or ids[-1] != ids[-2]:
        value = TYPICAL[kind(prefix.token_strings[-1])]
        return (token, True, value), value
    first, run, value = carry
    if run and token == first and value <= TYPICAL["repeated symbols"]:
        return carry, 2.0 * value
    return (first, False, value), 0.0

programs.sol:
"""A sparse EVEN / ven-syllable approximation.

EVEN is stronger capitalized or after clause links, and weaker after
coordination, determiners and copulas. Identifier and recent mathematical
contexts lower its value. Related spelling families (oven, aven, ven,
vent) and a few related adverbs have their own levels. Within a word,
distinguish nasal continuations of v from r continuations. Romanization
extends these spelling heuristics to other alphabets; Chinese name
transliterations and Japanese labial+n have additional rules.

Remember the previous token and 160 characters, resetting at document
boundaries. Most tokens get zero. This is not a semantic/phonetic parser
and deliberately leaves unrelated rare responses unexplained.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
MATH = re.compile(
    r'\b(integer|exponent|parity|divisib\w*|modulo|fractions?)\b', re.I
)
NUMBER_MATH = re.compile(r'\b(odd|prime|perfect|power|digit)\w*\b', re.I)


@lru_cache(maxsize=20000)
def roman(s):
    return anyascii(s).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    recent = carry[2] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    w = s.strip(' _-./(')
    low, p = w.lower(), prev.strip().lower()
    value = 0.0

    if low == 'even':
        value = 4.0
        if w != low:
            value += 2.1
        if not s.startswith(' '):
            value -= 0.2
        if p in {'and', 'or', '&'}:
            value -= 1.3
        elif p in {',', ';', ':', '-'}:
            value += 0.7
        elif p in {'that', 'since', 'although', 'so', 'but'}:
            value += 1.1
        elif p in {'not', "'t", '’t', 'cannot'}:
            value += 0.5
        elif p in {'is', "'s"}:
            value -= 1.8
        elif p in {'be', 'was', 'are', 'been', 'being', 'were'}:
            value -= 1.0
        elif p in {'the', 'a', 'an', 'all'}:
            value -= 1.1
        elif p in {'can', 'may', 'might', 'will', 'could', 'would', 'should'}:
            value -= 0.9
        if '_' in s:
            value = min(value, 2.0)
        math_context = MATH.search(recent) or (
            NUMBER_MATH.search(recent) and any(c.isdigit() for c in recent)
        )
        if w == low and math_context and p not in {
            'that', 'since', 'although', 'so', 'but', 'not', "'t", '’t', 'cannot'
        }:
            value = min(value, 2.2)
    elif low == 'oven':
        value = 5.4
    elif low.endswith(('aven', 'avens')):
        value = 3.5
        if low == 'haven':
            value += 1.3 if w[:1].isupper() else -2.8
        elif low in {'heaven', 'heavens'}:
            value -= 1.3
    elif low.endswith('even') and low not in {'seven', 'eleven'}:
        value = 1.4 if low == 'uneven' else 2.3
    elif low == 'evening':
        value = 2.0 + (1.5 if w[:1].isupper() else 0.0)
    elif low in {'ven', 'vens'}:
        value = 3.9 + (1.5 if low == 'vens' else 0.0)
        if prev.lower().endswith('e'):
            value += 1.0
        if s.startswith(' '):
            value -= 1.3
        if p in {'pre', 'pro'}:
            value = min(value, 1.9)
    elif low == 'vern':
        value = 0.7 if s.startswith(' ') else 1.2
    elif low == 'vent':
        value = 1.9
        if p in {'inter', 'in'}:
            value = 0.7
    elif low == 'event':
        value = 0.4
    elif re.fullmatch('[aeiou]vn', low):
        value = 2.5
    elif low.endswith(('wen', 'wens')) and len(low) > 3:
        value = 2.0 if low.endswith('s') else 3.0
    elif low == 'vue':
        value = -0.9 if s.startswith('.') else -2.4
    elif low == 'ben':
        value = 0.5
    elif low in {'eben', 'даже'}:  # Related adverbs: German / Russian.
        value = 2.6

    if low != roman(w) and roman(w) in {'ven', 'vens'}:
        value += 2.0
    if w == '文':  # Mandarin wen; English-name transliterations.
        value += 1.1
        if prev in {'埃', '艾', '凯', '凱', '欧', '歐'}:
            value += 5.8

    # Syllables split at a token boundary: v + en, v + ar, etc.
    if s and prev and not s[0].isspace() and not prev[-1].isspace():
        x, before = roman(s), roman(prev)
        vowel = re.match('[aeiouy]+', x)
        tail = x[vowel.end():] if vowel else x
        nasal = (vowel and tail.startswith('n')) or x in {"n", "'n"}
        if re.search(r'v[aeiou]?$', before):
            if nasal:
                value += 0.3
                if s.isascii() and prev.isascii():
                    value += 0.5
                if s.isascii() and x in {'ens', 'ensen'}:
                    value += 5.9
                if x.startswith('en') and re.search('[aeiou]rv$', before):
                    value += 2.2
                if x == "'n":  # Elided vowels: ev'n, heav'n.
                    value += 7.0
            elif vowel and tail.startswith('r'):
                value -= 0.1 + (1.1 if x.startswith('a') else 0.0)
                if x.startswith('ar') and len(x) <= 3:
                    if re.search('[aeiou]v$', before):
                        value -= 1.3
            elif x.startswith('ue'):
                value -= 3.5 if x == 'ue' else 0.7
            elif x.startswith('v'):
                value -= 0.2
        elif re.search(r'b[aeiou]?$', before) and nasal:
            value += 2.5 if x in {'ens', 'ensen'} else 0.1
            if x in {'en', "en'"}:
                value += 0.7
        if s in {'ン', 'ん'} and before.endswith(('bu', 'vu', 've')):
            value += 9.0
    return (doc, s, (recent + s)[-160:]), float(value)

programs.haiku:
"""Fires on the spelling 'even' and its sound 'ven' in words such as even, Even, oven,
Haven, Steven and Ravens. Letters are counted across sub-word tokens, so 'Break' +
'even' also counts. Look-alikes (given, driven, proven, seven, eleven, event, prevent)
do not fire, and the verb 'haven't' does not. Mathematical 'even' (is even, or even)
fires less than the everyday word (even though, not even). A run of middle dots (··)
also fires a little, though the model does not use that part."""
READS = ()

MATH_BEFORE = ("is", "are", "be", "an", "or", "and", "was", "were", "odd", "&")

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word, prev = carry if carry else ("", "")
    if tok[:1].isspace() or not tok.isalpha():
        prev = word.lower()
        word = ""
    word = (word + tok).strip() if tok.isalpha() or tok[:1].isspace() else word
    w = word.lower()
    if tok.strip() and set(tok.strip()) == {"·"} and len(tok.strip()) >= 2:
        value = 1.2
    elif tok.strip().lower() == "vent":
        value = 2.0
    elif w.endswith(("iven", "uven", "proven")) or w in ("seven", "eleven"):
        value = 0.0
    elif w == "haven" and word[:1].islower():
        value = 0.0
    elif w in ("evening", "evenings"):
        value = 2.0
    elif w.endswith(("even", "aven", "ven", "vens")) or w in ("oven", "ovens"):
        if prev in MATH_BEFORE:
            value = 2.5
        elif word[:1].isupper():
            value = 6.0
        else:
            value = 4.0
    else:
        value = 0.0
    return (word, prev), value

programs.sol:
"""A negative cue for unknown people, choices and places.

Who/which/where are stronger in questions and after verbs of finding out
than in relative clauses. Chinese 'who' is especially strong, even as an
unfinished byte prefix; French and Russian equivalents also contribute.
Small first-token offsets are included, but most background activity is not.
"""
import re
import regex
import wordnet
from functools import lru_cache

READS = ()
WH = set('who whom whose whoever which where what how why'.split())
VERBS = set('''
    know see ask wonder tell determine decide find choose consider explain
    understand learn discover guess look define specify realize discuss examine
    seek check identify predict remember forget
'''.split())
PREPS = set('to of in at on from by with for about over into through under upon'.split())


@lru_cache(maxsize=1024)
def roots(word):
    return set(wordnet.base_forms(word)) | {word}


def value(token, before, raw_tail):
    word = token.strip().lower()
    words = re.findall(r'[A-Za-z]+', before) if word in WH else []
    last = words[-1].lower() if words else ''
    previous = words[-2].lower() if len(words) > 1 else ''
    plain = bool(re.search(r'[A-Za-z]\s*$', before))
    if word in WH:
        if token.strip().isupper():
            return -1.2 if word == 'who' else 0.0
        if not token[:1].isspace() and before[-1:].isalpha():
            return 0.0  # An identifier suffix, e.g. addWhere.
        verb = previous if last in {'exactly', 'just', 'really', 'out'} else last
        question = plain and bool(roots(verb) & VERBS)
        question |= plain and last in {'sure', 'unclear', 'uncertain'}
        if last in {'known', 'chosen', 'found', 'realized'}:
            question = False
        prep = plain and last in PREPS
        conjunction = plain and last in {'and', 'or', 'but'}
        capital = token.strip()[:1].isupper()
        seeing = question and bool(roots(verb) & {'see', 'guess', 'ask'})
        if word == 'who':
            if question or last in {'so', 'well', 'hey'}:
                return -5.2 if seeing else -3.8
            if capital:
                title = plain and words[-1].istitle() and last not in PREPS
                return -0.6 if title else -3.5
            if prep:
                return -3.5
            return -2.5 if conjunction else (-0.85 if before.rstrip().endswith(',') else -0.63)
        if word == 'which':
            if question:
                return -2.5 if seeing else -1.5
            if capital or conjunction:
                return -0.55
            if prep and last in {'to', 'on'}:
                return -0.45
            return -0.08 if token.startswith(' ') else 0.08
        if word == 'where':
            if question:
                return -2.0 if seeing else -1.4
            return -1.0 if prep else (-0.6 if capital or conjunction else -0.08)
        if word == 'whose':
            return -3.0 if question or capital else -0.15
        return {'whom': -0.8, 'whoever': -1.6, 'why': -0.23}.get(word, -0.10)
    if word in {'谁', '誰'}:
        japanese = regex.search(r'[\p{Hiragana}\p{Katakana}]', before)
        return -2.5 if word == '誰' and japanese else -8.5
    if '谁' in word or '誰' in word:
        return -4.5
    if word == 'qui' and token.strip() != 'QUI':
        return -1.1 if token.startswith(' ') or not before[-1:].isalpha() else 0.0
    if raw_tail.endswith('谁'.encode()[:2]):
        return -8.2
    if raw_tail.endswith('誰'.encode()[:2]):
        return -1.2
    if token.isalpha() and not token[:1].isspace():
        tail = re.search(r'[A-Za-z]+$', before)
        joined = (tail[0] + token).lower() if tail else ''
        if joined in {'who', 'whose', 'which', 'where'}:
            return {'who': -6.0, 'whose': -3.0, 'which': -1.5, 'where': -1.0}[joined]
    return {
        'где': -1.0, 'quem': -1.3, 'quien': -0.65, 'quién': -0.65,
        '哪': -1.7, '哪个': -1.7, '哪個': -1.7, '哪些': -0.6,
        '哪里': -1.0, '哪裡': -1.0, '哪儿': -1.0, '哪兒': -1.0,
    }.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = b'' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    recent = (before + prefix.token_bytes[-1])[-240:]
    if not before:
        latin = bool(re.fullmatch(r'[ A-Za-z]+', token))
        offset = 0.22 if token[:1].isspace() or token[:1].isupper() else 0.08
        return (doc, recent), (offset if latin else 0.0)
    prediction = value(token, before.decode('utf-8', 'ignore'), recent)
    return (doc, recent), prediction

programs.haiku:
"""Wh-word detector v2: token identity plus whether the wh-word opens an embedded question
or free relative (after a verb, preposition or conjunction) rather than following a comma or noun."""
WH_STRENGTH = {" who": -0.8, " Who": -2.4, " WHO": -1.5, " whom": -0.75, " whose": -0.4,
               " which": -0.15, " Which": -0.7, " where": -0.15, " Where": -0.25,
               " qui": -1.0, "谁": -8.0, "誰": -3.0, "哪": -1.0, "哪些": -1.0, " где": -0.85}
WH_WORDS = {" who", " Who", " WHO", " whom", " whose", " which", " Which", " where", " Where"}
# words after which a wh-word starts an embedded question or free relative
OPENERS = {" know", " about", " to", " and", " or", " on", " over", " of", " consider", " see",
           " wondering", " think", " ask", " asked", " tell", " learn", " decide", " whether",
           " find", " understand", " determine", " figure", " matter", " depends", " in", " at",
           " from", " by", " with", " for", " is", " are", " was", " Is", " how", " what"}
def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    base = WH_STRENGTH.get(cur, 0.0)
    if cur not in WH_WORDS or len(prefix.token_strings) < 2:
        return None, float(base)
    prev = prefix.token_strings[-2]
    if prev.strip() == "," or prev == ",":
        mult = 0.0 if cur.strip().lower() in ("which", "where") else 1.0
    elif prev in OPENERS:
        mult = 3.0
    else:
        mult = 1.0
    return None, float(base * mult)
