programs.sol:
"""An initial-context pulse, plus negative chat and tool delimiters.

The initial pulse lasts while the document contains only repetitions of its
first token. Its size depends on text shape: capitals and words exceed
punctuation, numbers and East Asian text. Auxiliaries and conjunctions give
smaller pulses than other English words. Ordinary later text is nearly zero,
except for chat/control delimiters and small comment-marker responses.
"""
import regex

READS = ()
AUXILIARIES = frozenset('is am are was were be been being do does did have has '
                        'had can could may might must shall should will would'.split())
CONJUNCTIONS = frozenset('and but or nor so yet if as because although though '
                         'while whereas unless until than whether'.split())
PRONOUNS = frozenset('i me you he him she her it we us they them my your his '
                      'its our their myself yourself himself herself itself '
                      'ourselves themselves'.split())


def initial_pulse(token):
    word = token.strip()
    if token == '<|im_start|>':
        return 6.75
    if token.startswith('<|'):
        return 0.0
    if not word:
        if '\n' in token or '\r' in token:
            return 3.3
        return 3.2 if len(token) == 1 else 6.7
    if any(ch.isascii() and ch.isalpha() for ch in word):
        if token[0].isspace():
            if word.lower() in AUXILIARIES | CONJUNCTIONS:
                return 6.5
            if word.lower() in PRONOUNS:
                return 7.9
            return 8.85
        if not word[0].isalpha():
            return 9.5  # identifier fragments with a punctuation prefix
        return 13.3 if word[0].isupper() else 10.9
    if regex.search(r'[\p{Script=Han}\p{Script=Hiragana}'
                    r'\p{Script=Katakana}]', word):
        return 6.8
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 12.5 if word[0].isupper() else 8.6
    if any(ch.isalpha() for ch in word):
        return 9.4
    if word[0].isdigit():
        return 7.15
    if '\ufffd' in word:
        return 5.3
    if word in ('#', '//'):
        return 8.0
    return 4.0 if len(word) == 1 else 6.8


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = (len(prefix.document_ids) == 1 or
                    prefix.document_ids[-1] != prefix.document_ids[-2])
    uniform = new_document or (carry[1] and carry[0] == prefix.token_ids[-1])
    if uniform:
        value = initial_pulse(token)
    elif token == '<|im_start|>':
        value = -2.67
    elif token in ('<think>', '<tool_call>'):
        value = -2.08
    elif token in ('</tool_call>', '<tool_response>', '</tool_response>'):
        value = -2.25
    elif token == '</think>':
        value = -0.88
    elif token.strip() == '//':
        value = 0.35
    elif token.strip() == '#':
        value = 0.2
    else:
        value = 0.0
    return (prefix.token_ids[-1], uniform), value

programs.haiku:
"""Layer-1 MLP unit 510 (down_proj) as a vowel-"u" detector.

The unit goes negative on tokens whose spelling carries the vowel u, the sound
of "but", "use", "unit", "public", "run". Standalone U/u and US/user/use/up
are strongest; other u-words are moderate; u inside digraphs such as ou, qu,
ur, au (our, your, would, query, return) is weak, and so is the pronoun " us".
Tab indentation is mildly negative, replacement characters slightly, and
other word fragments barely. Everything else is about 0. Predictions are
negative numbers in the unit's own units.
"""

READS = ()

U_CHARS = set("uUúüùûūÚÜÙÛуУυΥ")  # latin u with accents, Cyrillic у, Greek upsilon
U_SINGLE = {"u", "ú", "ü"}
U_WORDS = {"us", "user", "use", "used", "using", "uk", "ur", "um", "un", "ut", "ul", "up"}
WEAK_SPELLINGS = ("ou", "qu", "ur", "au")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    if s == " us":
        return carry, -0.1
    if w in U_SINGLE:
        return carry, -2.3
    if w in U_WORDS:
        return carry, -1.3
    if any(c in U_CHARS for c in s):
        if any(d in w for d in WEAK_SPELLINGS):
            return carry, -0.4
        return carry, -0.8 if s.startswith(" ") else -1.0
    if s.startswith("\t"):
        return carry, -0.6
    if "�" in s:
        return carry, -0.2
    if s.isalpha() and not s.startswith(" "):
        return carry, -0.1
    return carry, 0.0

programs.sol:
"""An of/genitive-preposition detector with grammatical left-context gating.

Prefixes like 'and of', 'is of', and sentence-initial 'Of' give the largest
responses; noun-complement uses of 'of' are mostly suppressed.

Numbers and partitives give smaller responses. Other listed genitives use
recent Romance function words to distinguish prose from English fragments and
code, then use grammatical word classes and verb/noun endings. Response levels
are rounded training estimates for these contexts, not individual-token fits.
Only the last 100 characters are remembered; document boundaries reset them.
"""
import re
from functools import lru_cache
import wordnet
import inflect

READS = ()
GENITIVES = {'de': 1., 'd': 1., 'di': .9, 'du': .65, 'del': .65,
             'da': .5, 'des': .25, 'das': .25, 'do': .25, 'dos': .25,
             'von': .5, 'van': .3, 'della': .5, 'delle': .4, 'dei': .5}
COORDINATION = set('and or but nor yet although also'.split())
COPULAS = set('be am is are was were been being become becomes became remain'.split())
PARTITIVES = set('all both most much many few several some any each either '
                 'neither none which that those these enough'.split())
_inflection = inflect.engine()
NUMBERS = {_inflection.number_to_words(i) for i in range(2, 21)}
NUMBERS.update({'hundred', 'thousand'})
COMPOUNDS = set('out because instead regardless irrespective off'.split())
ROMANCE_CUES = set('le la les un une des du de et est sont dans pour sur avec '
                   'qui que ce cette ces se il elle nous vous à au aux mais '
                   'ne pas en el los las una y es son con por para del al su '
                   'como más sus pero ha han no lo gli uno e è sono che di '
                   'della per nel nella si non più dei sul da uma os é são '
                   'com em do dos das na não foi'.split())
FOREIGN_COORD = set('et ou mais donc car ni y e o pero ma anche und oder en'.split())
FOREIGN_AUX = set('est sont être etre été était étaient etait etaient suis sommes '
                  'êtes sera serait seront fut soit fait font faire ayant avoir '
                  'a ont avait avaient ait aura es son ser era fue ha han he '
                  'has hemos había estado estoy è sono ho hai hanno abbiamo '
                  'são é foi ist sind'.split())
FOREIGN_PREP = set('afin avant après apres près pres lors hors autour loin '
                   'auprès aupres avec sans pour par à de di per'.split())
NEGATION = set('not never non ne pas plus no não nao'.split())
VERB_ENDINGS = ('er', 'ir', 're', 'é', 'ée', 'és', 'ées', 'ait', 'ais',
                'aient', 'ez', 'ons', 'ent', 'ant', 'ando', 'endo', 'ado',
                'ido', 'ato', 'uto', 'ito', 'are', 'ire', 'ere', 'ar')
NOUN_ENDINGS = ('tion', 'tions', 'sion', 'sions', 'ment', 'ments', 'dade',
                'ción', 'zione', 'zioni', 'ité', 'ités', 'ance', 'ence')

@lru_cache(maxsize=8192)
def lexical_info(word):
    return (wordnet.parts_of_speech(word), set(wordnet.base_forms(word)))


def response(token, before):
    raw = token.strip()
    word = raw.lower()
    if word != 'of' and word not in GENITIVES:
        return 0.0
    if not before:
        return -0.039
    if not token.startswith(' ') and before[-1].isalnum():
        return 0.0
    words = re.findall(r"[^\W\d_]+|\d+", before)
    prev = words[-1].lower() if words else ''
    end = before.rstrip()
    if word == 'of':
        if raw == 'OF':
            return 0.093
        if end.endswith((',', ';', ':')):
            return 4.997
        new_clause = before.endswith('\n') or end.endswith(
            ('.', '!', '?', '"', '”', ']'))
        if raw == 'Of' and new_clause:
            return 6.347
        if end.endswith(('(', '"', '“', "'")):
            return 1.424
        if prev in COORDINATION:
            return 7.523
        if prev in COPULAS:
            return 6.963
        if prev in COMPOUNDS:
            return 0.064
        if prev == 'one':
            return -0.093
        if prev in NUMBERS or prev.isdigit():
            return 0.747
        if prev in PARTITIVES:
            return 0.692
        if prev == 'first':
            return 2.349
        if prev.endswith(('self', 'selves')):
            return 3.61
        if prev == 'as':
            return 2.632
        if prev in NEGATION:
            return 3.473
        pos, bases = lexical_info(prev)
        if bases & {'think', 'dream'}:
            return 1.035
        if prev in {'free', 'clear', 'devoid', 'independent'}:
            return 1.83
        if 'noun' in pos:
            return 0.015
        if 'verb' in pos:
            return 0.99
        if 'adverb' in pos:
            return 2.138
        if 'adjective' in pos:
            return 0.704
        return 0.219
    scale = GENITIVES[word]
    recent = [w.lower() for w in words[-18:]]
    if sum(w in ROMANCE_CUES for w in recent) < 3:
        return 0.131 * scale
    if raw[0].isupper() and (before.endswith('\n')
                             or end.endswith(('.', '!', '?'))):
        return 1.616 * scale
    if end.endswith((',', ';', ':')):
        return 3.703 * scale
    if prev in FOREIGN_COORD:
        return 4.373 * scale
    if prev in FOREIGN_AUX:
        return 4.393 * scale
    if prev in NEGATION:
        return 4.119 * scale
    if prev in FOREIGN_PREP:
        return 2.831 * scale
    if prev.endswith(NOUN_ENDINGS):
        return 0.073 * scale
    if prev.endswith(VERB_ENDINGS):
        return 1.917 * scale
    return 0.614 * scale


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-100:]), value
